window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_002"]={"n":"耶律铸","dyn":"元","poems":[{"t":"六国朝令 家园席间作","f":"曲","c":["鸣珂绣毂，锦带吴钩。","曾雅称、量金结胜游。","信人间无点事、可挂心头。","须知，不待把闲情酿做闲愁。","只恐落高人第二筹。","歌云容裔，梦雨迟留。","殢惯振芳尘，不夜楼。","光饰仙春盛迹，点化温柔。","索教颓纵惜花人，标榜风流。","快入醉乡来，刘醉侯。"]},{"t":"太常引 题李隐君文集","f":"曲","c":["扣声寂寞播阳春。","看流水混行云。","大雅扶轮。","忍颜继、齐梁后尘。","清风明月，四时长在，光景自长新。","不见谪仙人。","更何处、乘槎问津。"]},{"t":"忆秦娥 赠前朝宫人琵琶色兰兰","f":"曲","c":["恨凝积。","佳人薄命尤堪惜。","尤堪惜。","事如春梦，了无遗迹。","人生适意无南北。","相逢何必曾相识。","曾相识。","恍疑犹览，内家园籍。"]},{"t":"木兰花慢 丙戌岁游永安故宫遍览太液池莲瀛桂窟殿天香阁同坐中诸客感而赋此","f":"曲","c":["花枝临太液，解语入温柔。","衒桂窟低迷，天香飘荡，倒影迟留。","须知画图难足，更青山环抱帝王州。","凤吹绕瀛洲。","记水浅蓬莱，尘扬沧海，一醉都休。","华胥梦，虽无迹，甚鼎湖、龙去水空流。","青鸟不来难问，玉妃几度仙游。"]},{"t":"南乡子 送人北行入燕作","f":"曲","c":["匹马赴严宸。","将谓青云上致身。","不是男儿容易事，风尘。","水远山长愁杀人。","离别若为情。","雪暗西山泪满巾。","还忆夜来分手处，天津。","桃李无言各自春。"]},{"t":"眼儿媚 醴泉和高斋过炀帝故宫","f":"曲","c":["隔江谁唱后庭花。","烟淡月笼纱。","水云凝恨，锦帆何事，也到天涯。","寄声衰柳将烟草，且莫怨年华。","东君也是，世閒行客，知过谁家。"]},{"t":"满庭芳 西园席间用人韵","f":"曲","c":["酒阵诗坛，征兵命将，得无倾动华筵。","拟勤春事，还自要相先。","天地元如逆旅，应自愧、不驻流年。","凭谁问，姮娥心事，何惜月长圆。","西园张乐地，献歌呈舞，燕扰莺喧。","尽未妨颓玉，锦瑟旁边。","脱落尘凡健笔，终不负、兴染芳烟。","欢缘在，判家视草，仍是玉堂仙。"]},{"t":"鹊桥仙 阆州得稼轩乐府全集有西江月而今何事最相宜宜醉宜閒宜睡或曰不若道宜笑宜狂宜醉请足成之","f":"曲","c":["皇都门外，玄都观里。","露井树傍歌意，先生凭恁作生涯，只嘲柳嘲桃嘲李。","酒龙歌凤，莫相回避。","就取逢场戏。","且听人劝要推移，更宜笑宜狂宜醉。"]},{"t":"凯歌乐词九首 其一 南征捷","f":"七言绝句","c":["食言自是是诬天，游鼎鱼疑戏洞渊。","征信自从天北极，目无江表已多年。"]},{"t":"凯歌乐词九首 其二 拔武昌","f":"七言绝句","c":["设奇包敌纵蒙冲，绝似飘风捲断蓬。","填得大江流不得，先声已不见江东。"]},{"t":"凯歌乐词九首 其三 战芜湖","f":"七言绝句","c":["舳舻千里蔽江湖，擿挑楼船为骚除。","先直前锋三十万，一通严鼓尽为鱼。"]},{"t":"凯歌乐词九首 其四 下江东","f":"七言绝句","c":["举国全兵失要冲，可无一策抗元戎。","细推馀百年来事，合册江神拜上公。"]},{"t":"凯歌乐词九首 其五 定三吴","f":"七言绝句","c":["奋威骁骑下三吴，神将飞驰一丈乌。","视彼众虽千百万，黎民游动跨玄驹。"]},{"t":"凯歌乐词九首 其六 克临安","f":"七言绝句","c":["拟歌陌上行人去，犹是传歌陌上花。","花解语时应也问，即今春色媚谁家。"]},{"t":"凯歌乐词九首 其七 江南平","f":"七言绝句","c":["横野万艘金翅舰，总戎一册玉铃篇。","长江岂限天南北，万劫坤灵戴一天。"]},{"t":"凯歌乐词九首 其八 制胜乐辞","f":"七言绝句","c":["燀耀威灵结陈锋，信争敌忾献殊功。","全师保胜清时策，元在天声震荡中。"]},{"t":"凯歌乐词九首 其九 圣统乐辞","f":"七言绝句","c":["幸值圣明临御日，更逢文轨混同时。","升薰天地神功颂，润色光天统业辞。"]},{"t":"后凯歌词九首 其一 奇兵","f":"七言绝句","c":["一旅奇兵出禁宸，略时弹压定惊尘。","萧条万里无遗寇，信道天家又得人。"]},{"t":"后凯歌词九首 其二 沙幕","f":"七言绝句","c":["金节煌煌下玉京，鱼丽三十六屯兵。","一军电激穿沙幕，万燧云繁战野营。"]},{"t":"后凯歌词九首 其三 枭将","f":"七言绝句","c":["枭骑云腾自北征，领军枭将最驰声。","横穿外壁风前陈，直捣中坚月下营。"]},{"t":"后凯歌词九首 其四 翁科","f":"七言绝句","c":["蜂屯蚕簇乱山窝，蚁动鹑居乱草坡。","沾体露形千万指，恳祈天语许降和。"]},{"t":"后凯歌词九首 其五 崲峹","f":"七言绝句","c":["畔敌休矜战骑多，纷罗区落遍山坡。","那知未鼓投戈地，待阅前徒竞倒戈。"]},{"t":"后凯歌词九首 其六 降王","f":"七言绝句","c":["控黄龙戍争雄地，登白龙堆将战场。","奇正相生神算在，粪除勍敌献降王。"]},{"t":"后凯歌词九首 其七 科尔结","f":"七言绝句","c":["初若疾雷威似虎，复如脱兔速于神。","想当持节为飞将，袛是今如著翅人。"]},{"t":"后凯歌词九首 其八 露布","f":"七言绝句","c":["露布突驰争逐日，电鞭搀递斗追风。","只自向时龙尾道，群来云集万宁宫。"]},{"t":"后凯歌词九首 其九 烛龙","f":"七言绝句","c":["封略谁容限烛龙，终将天地入牢笼。","云兴飙起威名将，也好先收弟一功。"]},{"t":"凯乐歌词曲九首 其一 征不庭","f":"七言绝句","c":["天下英雄入彀中，得无威震折遐冲。","会须六幕氛霾了，化日常明照九重。"]},{"t":"凯乐歌词曲九首 其二 取和林","f":"七言绝句","c":["龙飞天府玉滦春，德水清流复旧痕。","自非电断光前烈，谁得重沾雨露恩。"]},{"t":"凯乐歌词曲九首 其三 下龙庭","f":"七言绝句","c":["翠华一动下龙庭，生意还从一气生。","乐国得非为寿域，圣人须自有金城。"]},{"t":"凯乐歌词曲九首 其四 金莲川","f":"七言绝句","c":["金莲川上水云间，营卫清沈探骑閒。","镇西虎旅临青海，追北龙骧过黑山。"]},{"t":"凯乐歌词曲九首 其五 析木台","f":"七言绝句","c":["辟易天威与胜风，一场摧折尽奇锋。","西北龙荒三万里，并随驱策入提封。"]},{"t":"凯乐歌词曲九首 其六 驻跸山","f":"七言绝句","c":["辕门鼓角扬屯戍，营幕旌旂掣朔风。","相与山河雄帝宅，威棱尤壮受降宫。"]},{"t":"凯乐歌词曲九首 其七 益屯戍","f":"七言绝句","c":["睿算深筹势万全，益屯貔虎在雄边。","东连玉塞西通海，南接金山北到天。"]},{"t":"凯乐歌词曲九首 其八 恤降附","f":"七言绝句","c":["一新污俗浴恩波，天地閒人感慨多。","我泽如春民似草，圣元天子布阳和。"]},{"t":"凯乐歌词曲九首 其九 著国华","f":"七言绝句","c":["四海承风著国华，更无龙虎缦纷拿。","际天所覆人閒地，今日都须是一家。"]},{"t":"后凯歌词九首 其一 战卢胊","f":"七言绝句","c":["神策霆声振九区，纵兵雷合战卢胊。","竞将蔽野冲云陈，只片时閒埽地无。"]},{"t":"后凯歌词九首 其二 区脱","f":"七言绝句","c":["云屯区脱会天兵，云动龙趋从北平。","驰驱日逐飞龙陈，夜薄花门偃月营。"]},{"t":"后凯歌词九首 其三 克夷门","f":"七言绝句","c":["蚁扰蜂喧笑骑过，鼓儳争自落长河。","人人斗说空鞍马，不似今番数最多。"]},{"t":"后凯歌词九首 其四 高阙","f":"七言绝句","c":["骈驰追锐翼摧锋，枭獍窠巢一夜空。","光射铁衣寒透彻，冷风如箭月如弓。"]},{"t":"后凯歌词九首 其五 战焉支","f":"七言绝句","c":["羽檄交驰召虎贲，期门受战已黄昏。","信剪黥鲵知有处，山川争震荡乾坤。"]},{"t":"后凯歌词九首 其六 涿邪山","f":"七言绝句","c":["鼓噪欢山撼涿邪，飞龙㢋翼掩螣蛇。","露营罢缭神锋弩，云陈犹轰霹雳车。"]},{"t":"后凯歌词九首 其七 金满城","f":"七言绝句","c":["寄重旌分阃外忧，顺时驱率万貔貅。","回临金满城边日，奄夺蒲昌海气秋。"]},{"t":"后凯歌词九首 其八 金水道","f":"七言绝句","c":["旁张虎翼搀风陈，直突龙城袭雪山。","连夜可侦金水道，防秋岂在玉门关。"]},{"t":"后凯歌词九首 其九 京华","f":"七言绝句","c":["横车组练似春花，来自天涯与海涯。","说道埽除氛祲了，凯还歌奏到京华。"]},{"t":"德胜乐二首 其一","f":"五言绝句","c":["揖让跻龙历，讴歌适凤符。","凿空十万里，攘地几千都。"]},{"t":"德胜乐二首 其二","f":"五言绝句","c":["神断光宏业，天威震八区。","控弦三百万，自号感恩都。"]},{"t":"骑吹曲辞九首 其一 金奏","f":"七言绝句","c":["大夏王庭前纳款，大秦归义继来降。","舞鸾歌凤音相和，未许天山数帝江。"]},{"t":"骑吹曲辞九首 其二 玉音","f":"七言绝句","c":["燕巢飞幕负恩私，远近嚣然共一辞。","烈圣玉音明在耳，敢忘龙道请降时。"]},{"t":"骑吹曲辞九首 其三 白霞","f":"七言绝句","c":["前骑传声掩白霞，后军犹未过乌沙。","势须贵合为猿臂，相制尤当似犬牙。"]},{"t":"骑吹曲辞九首 其四 眩雷","f":"七言绝句","c":["毳幕云罗寒露野，羽旄星属眩雷乡。","悔将觇望风尘眼，不为长观日月光。"]},{"t":"骑吹曲辞九首 其五 塞门","f":"七言绝句","c":["逻骑纷纷与寇军，递相窥隙伺残昏。","忆曾延敌临高阙，示敛疑兵突塞门。"]},{"t":"骑吹曲辞九首 其六 受降山","f":"七言绝句","c":["望风降附祈为地，披露精诚示所天。","若非上将龙旂下，会是中军虎帐前。"]},{"t":"骑吹曲辞九首 其七 凤林关","f":"七言绝句","c":["祇须尽敌巡乌水，未可移屯过凤林。","切索更虞蜂虿毒，恐还争纵虎狼心。"]},{"t":"骑吹曲辞九首 其八 司约","f":"七言绝句","c":["留犁可要教挠酒，径路何为更契金。","事岂出人明算外，慕容虚美漫薰心。"]},{"t":"骑吹曲辞九首 其九 军容","f":"七言绝句","c":["虽许王侯复正封，养威尤可耀军容。","渔阳马厌银山草，鸡鹿屯营铁堠峰。"]},{"t":"后骑吹曲词九首 其一 吉语","f":"七言绝句","c":["交锋接矢无虚月，按甲休兵定几时。","计日必须闻吉语，敢先期献凯歌辞。"]},{"t":"后骑吹曲词九首 其二 金山","f":"七言绝句","c":["黄花堆上冷云閒，犷骑雷奔去又还。","说敌纷争自相溃，回戈霆斗过金山。"]},{"t":"后骑吹曲词九首 其三 天山","f":"七言绝句","c":["曜我皇威下帝台，灵旂直傃北庭开。","定应六出奇寒雪，瀚海阴风结陈来。"]},{"t":"后骑吹曲词九首 其四 处月","f":"曲","c":["陈兵阔里黄芦淀，转战斜车白草?。","飞骑星驰穿处月，追亡逐北入沙陀。"]},{"t":"后骑吹曲词九首 其五 独乐河","f":"七言绝句","c":["贝冑星离争射日，蜂旗云合迥生风。","雷驰霆击相纷薄，独乐河边水草中。"]},{"t":"后骑吹曲词九首 其六 不周","f":"七言绝句","c":["熊罴此去从天定，枭獍当来自不周。","清一八纮天意在，已教克复了神州。"]},{"t":"后骑吹曲词九首 其八 逻逤","f":"七言绝句","c":["磨崖金字昆崙颂，勒石银书逻逤铭。","且述要知方略在，圣人不战屈人兵。"]},{"t":"后骑吹曲词九首 其九 柔服","f":"七言绝句","c":["柔服禺强总四溟，神开宝历见时清。","夜陪万国升平望，蹈咏清风播颂声。"]},{"t":"古战城南","f":"五言古诗","c":["结陈背南河，指顾望城北。","冠军申号令，谓彼是劲敌。","今朝一战在，有国与无国。","但得社稷存，此命不足惜。","风云为动色，士卒为感激。","奇正遽雷合，横冲奋霆击。","雌雄势未决，忽忽日将匿。","以剑指羲和，挥戈呼天日。","天地有情时，敢乞饶一掷。","貔虎张空弮，搏战到昏黑。","忽焉如海泄，声震裂区域。","对面不见人，何许不追袭。","平明案战所，涧壑尽平碛。","毕贺雪前耻，有力于王室。","拜诏未央宫，哀恳辞封邑。","五湖旧烟景，先师有遗迹。"]},{"t":"战城南","f":"曲","c":["自来古战场，多在长城南，少在长城北。","茫茫白骨甸，如何直接黄龙碛。","或云自从汉武开西域，耗折十万众，博得善马数十匹。","奋军势务鏖击往来谁，洗兵赤河水犹赤。","终弃轮台地，其地于中国。","失之且何损，得之本无益。","历计其所得，皆不偿所失。","虽下哀痛诏，追悔将何及。","此是万万古，华夏覆车辙。","底事夤缘其轨迄季唐，竞喜边功好大矜英哲。","明皇不虑渔阳厄，万里孤军征碎叶。","只轮曾不返，得无五情热。","暴殄生灵涂草莽，忍徇虚名为盛烈。","君不见世间人心固结，是谓帝王真统业。","君不闻四海内有美谈，至元天子平江南，何曾漂杵与溺骖。","圣人有金城，贵谋贱战，不战屈人兵。"]},{"t":"结袜子二首 其一 前结袜子","f":"七言绝句","c":["五凤声腾白日光，牧野昏荒惨无色。","精诚感激致师人，叱咤雷霆觉天窄。"]},{"t":"结袜子二首 其二 后结袜子","f":"七言绝句","c":["未应一吐明月珠，便欲延光万千载。","诸吞枭獍剪鲸鲵，直蹴昆崙过西海。"]},{"t":"前突厥三台 其一","f":"曲","c":["?骑生马射雕儿，恰似征西小月氏。","笑说汉家将野战，得非是我受降时。"]},{"t":"前突厥三台 其二","f":"七言绝句","c":["雁门关北分降地，马邑山南已拜旗。","尽道汉家无顾藉，锦帆终不有迥期。"]},{"t":"后突厥三台 其一","f":"七言绝句","c":["陈云寒压渭桥低，四野惊雷殷鼓鼙。","约定引还云骑去，一时争喷北风嘶。"]},{"t":"后突厥三台 其二","f":"七言绝句","c":["貔虎扬威指顾閒，先声已碎玉门关。","向来香史情何在，已说元戎逼铁山。"]},{"t":"婆罗门六首 其一","f":"七言绝句","c":["热海气蒸为喜雨，冻城寒结就愁阴。","中心甚欲期真宰，教使人知造物心。"]},{"t":"婆罗门六首 其二","f":"七言绝句","c":["雪海迤延穷地界，雪山迢递际天涯。","但为日月光临处，终不曾偏照一家。"]},{"t":"婆罗门六首 其三","f":"七言绝句","c":["青岭亘如颓碧落，赤河长似浸红霞。","是天柱折天倾处，龙战重渊尚攫拿。"]},{"t":"婆罗门六首 其四","f":"七言绝句","c":["黄草泊围青草甸，白杨河绕绿杨堤。","依然名是参天道，谁使唯闻战马嘶。"]},{"t":"婆罗门六首 其五","f":"七言绝句","c":["弓月山风长似箭，烛龙军火乱如星。","祇除尽挽天河水，可洗兵尘战地腥。"]},{"t":"婆罗门六首 其六","f":"七言绝句","c":["黑水且谁为翠水，白山元自是冰山。","得非烟容乘龙火，为煽洪炉到世间。"]},{"t":"上云乐","f":"曲","c":["金天老文康，平居隘神州。","金丹清真仙，相将汗漫游。","同流六合栖迟七丘，涉历八表盘桓十洲。","鹏其化，龙其变。","地轴为之回其运，天轮为之平其转。","日域为其上阳宫，月窟为其清凉殿。","鸑鷟是家鸡，狻猊是家犬。","真乐万春为局促，待把三光更舒展。","非圣不足知，天长将地远。","扶桑有时枯，蒙汜有时竭。","南山有时摧，钧天有时阕。","殊度仙曲拟进帝阙，九成玄云六变绛雪。","五色成文而不乱度，可插振芳声腾浩劫。","上天下地惟康老，毕竟谁能知岁月。","玄都仙伯，太山老叟，延致异鸟，名曰希有。","一翼左覆东王公，一翼右覆西王母。","得人备羽驾，故能出入游造化，逍遥巡宇宙。","感麟凤，在郊薮，至道之国常为称首。","骤来辙敢恋月明，表其老耋知去就。","拥仙仗，携仙友。","褒拜圣君奉神祝，凤箫在前鼍鼓在后。","玉笙在左，锦瑟在右。","作天乐，献天授。","若鸾自歌凤自舞，焚返魂香顶玉斗。","健舞起自补天年，浩歌发自谈天口。","仍倚凤台曲，凤凰和九奏。","南极老人称觞北斗挹酌天酒，愿与九州四海同上千万岁寿。"]},{"t":"夜起来","f":"五言古诗","c":["是处声歌席，一一凝尘埃。","羞掩合欢帐，独烛夜明苔。","徙倚立中庭，候虫一何哀。","满天秋色里，雁过黄金台。","所愿随清风，明月入君怀。","中心有劳结，期以向时开。","颓想就珍簟，远出绕兰阶。","美人来几时，知人起夜来。"]},{"t":"采荷调","f":"曲","c":["荷盘承露珠，何时成夜光。","荷盖承日华，何地得清凉。","虽曰是荷衣，且难作霓裳。","虽曰是荷杯，长难酌酒浆。","欲以荷作钿，不可饰时妆。","欲以荷为钱，不可博明珰。","拟荷如宝镜，不能照胆知肝肠。","拟荷如纨扇，不能鲜洁如雪霜。","其茎有轻丝，难织锦流黄。","其气有微馨，难剂水沈香。","有名无实不足取，似是而非良可伤。","流萤将拟流火乌，亦与姬发呈休祥。"]},{"t":"大道曲","f":"五言古诗","c":["春风吹绣陌，花满帝乡树。","绿柳袅芳烟，细雨黄金缕。","分明须尽是，引荡人心处。","车马往来尘，尽结成红雾。","楼上琵琶声，倚歌临大路。","郑重且休教，放得春回去。"]},{"t":"玉华盐三首 其一","f":"七言绝句","c":["玉华仙咏玉华盐，爱玉华盐分外甜。","但是梨花春在处，不消重设却寒帘。"]},{"t":"玉华盐三首 其二","f":"七言绝句","c":["玉妃隐映水晶帘，相与天花舞画檐。","玉洁冰清诚可爱，不应仍更有人嫌。"]},{"t":"玉华盐三首 其三","f":"七言绝句","c":["瑞雪香融注玉蟾，羡谁家醉捲珠帘。","风流柳絮因风起，只谢娘宜唱是盐。"]},{"t":"沐浴子","f":"五言律诗","c":["濯缨与濯足，应欲任其真。","沐芳及浴兰，应务洁其身。","难洗耳中事，易洗心上尘。","世閒原有耳，常是洗心人。"]},{"t":"筑城曲","f":"七言绝句","c":["一行杵后一行锥，只是嫌虚恨役迟。","谁谓筑城坚不得，坚城岂在隐金椎。"]},{"t":"古意","f":"五言古诗","c":["黄鹄巢高林，鼋鼍穴深渊。","且各独抽宿，人独胡不然。","释耕于陇上，妻子耘其前。","人笑苦畎亩，何以遗子孙。","聊以一二答，不可求备论。","人皆遗以危，我独遗以安。","春风吹布袖，云满鹿门山。"]},{"t":"游仙","f":"五言古诗","c":["绛节拥红云，凤吹随鸾扇。","游历万华宫，转宴诸仙殿。","金母愿接欢，玉真求识面。","为我问时人，谁曾是媒援。","高蹈步天衢，真游不知倦。","又遇西王母，屡会瑶池宴。","前后三千年，蟠桃开一遍。","为我问群仙，几见春风面。"]},{"t":"真游挟飞仙","f":"五言古诗","c":["真游挟飞仙，悬居何缥缈。","琪树不知秋，玉庭长似晓。","碧落无纤翳，天衢净如埽。","底许吟真声，仙韶动云表。","容与太素域，时复随青鸟。","朝游阆风苑，夕宴蓬莱岛。","昌城玉蕊花，昆墟玉红草。","可醉亦可玩，堪期后天老。"]},{"t":"问真宰","f":"五言律诗","c":["九色夜明珠，岂不有光彩。","终惜暗投人，含情欲谁待。","不惜珊瑚鞭，为君策驽骀。","此意竟何如，将可问真宰。"]},{"t":"小垂虹","f":"五言律诗","c":["虹光回曲绕，似令殊有待。","延留五色节，俄轸九华盖。","泰山是邱垤，黄虹细如带。","且昔欲谁知，游心在天外。"]},{"t":"随堤田家行","f":"曲","c":["日月会龙?，三农能事休。","犁杖倚空室，霜林卧羸牛。","十二三年閒，不如今岁秋。","田翁复何事，终不信眉头。","云以县官令，税租俱见收。","赤穷固有命，白著非自由。","又云有飞诏，少壮不一留。","半凿通济渠，半构迷藏楼。","言罢长叹息，涕泪交横流。","出门竟无语，回首漫夷犹。"]},{"t":"送胡寿卿南归","f":"五言古诗","c":["云山千万里，驰驿来帝阙。","君自到和林，寓居四踰月。","客中太寂寞，齑盐事孤洁。","锦衣归故里，薄官试盐铁。","匹马送君归，关山正黄叶。","征鸿声凄凄，悲笳鸣咽咽。","回首南州道，行人愁欲绝。","龙庭八月初，西风吹寒雪。","之子到甘棠，黄菊重阳节。","信笔作此诗，赠子以为别。"]},{"t":"送润甫行","f":"五言律诗","c":["拊节遏行云，浩歌山色里。","落絮积晴雪，东风吹不起。","远道趋鹏程，相思若为己。","揽辔入长烟，孤吟送春水。"]},{"t":"送友人还燕然","f":"五言古诗","c":["去年来帝阙，篱客正黄菊。","今年还燕然，春光明远目。","再三挽不留，归心何太速。","回首落花多，满川红簌簌。","驰驱万里程，阿谁慰幽独。","寂寂寒山行，寂寂寒山宿。","啼鸟几声迟，淡烟芳草绿。","东风千里人，明月半轩竹。","汉苑穴狐兔，姑苏走麋鹿。","功名半纸薄，兴亡等棋局。","可笑百年身，黄粱犹未熟。","不发离别叹，不唱阳关曲。","桃李醉逢场，夕阳倒船玉。"]},{"t":"对竹引","f":"五言律诗","c":["劲节淩云汉，沈沈翠如束。","春静锁窗深，惊风碎寒玉。","联声金凤凰，双飞夜双宿。","寂寞野桐花，年年老空谷。"]},{"t":"剪流水","f":"五言律诗","c":["莫持金剪刀，决绝剪流水。","莫将尺素书，慇勤托双鲤。","水岂是人情，鱼岂知人意。","鱼水自相亲，肯与人为计。"]},{"t":"同心结","f":"五言古诗","c":["湖中己种藕，湖边还种柳。","柳丝与藕丝，同在佳人手。","除是结同心，同心最长久。"]},{"t":"春自来","f":"五言古诗","c":["日月双飞翼，天地一遗卵。","无天地不卑，无日月不满。","时序相代谢，曾不偏寒暖。","昼夜互乘除，曾不有长短。","因究万物情，凝神顿舒缓。","断知春自来，何须候灰管。"]},{"t":"对酒","f":"五言古诗","c":["溇者沈杯杓，醇醴同一味。","狂风偃秋草，兰艾一同悴。","贤愚不同调，薰莸不同气。","如何昧去就，欲令为一致。","安得使贤愚，各分于一器。","安得使薰莸，各生于一地。","我志诚如斯，未审化工意。"]},{"t":"真金不死乡","f":"五言律诗","c":["真金不死乡，真境延閒燕。","灿灿琼瑶树，朝映朝元殿。","灵景一何清，寂然闻凤啭。","但见玉阶前，游蜂弄花片。"]},{"t":"对月吟拟诸公体","f":"五言古诗","c":["猎人设网罗，不挂月中兔。","岂无烹兔意，难求登月路。","月殿兔长生，人间几今古。","抱杵景徘徊，天狼空自苦。","樵者劳斧斤，不斫月中桂。","岂无薪桂思，难筹攀月计。","月殿桂长荣，人间几兴废。","倚镜影婆娑，天风摇不碎。","倾影听人歌，扬辉伴人舞。","何事在华筵，分明作宾主。","踪迹各无聊，乾坤两栖旅。","举酒寿姮娥，向人终不语。"]},{"t":"读新乐府","f":"曲","c":["霓裳羽衣曲，玉树后庭花。","不知相与迷春梦，绵历人閒弟几家。"]},{"t":"苦旱叹","f":"七言律诗","c":["六月亢旱田苗枯，自嗟自叹耕田夫。","差官咫尺征秋税，今岁田家一粒无。","饥民日日望霖雨，雨意欲成云散去。","天公胡不用老龙，年年祇被蛟螭误。"]},{"t":"观友人所藏佛牙","f":"七言古诗","c":["竺朝大夫哀群灵，出自大教拔幽沈。","汉明梦兆颇神异，具书梵释来千岑。","翕然风誉耸华夏，宝方精像辉云林。","传闻遗骨未灰朽，流散诸国磨古今。","朅来偶得见一齿，照座灿烂如璆琳。","当时左右广长舌，咀嚼风雷兴潮音。","烟如珠珞吐光怪，洗我旷劫尘埃襟。","目瞻顶礼固其事，岂必窣堵埋千寻。","凭君韫椟善持护，为绝阴怪窥窬心。"]},{"t":"漆城谣","f":"曲","c":["漆城光荡荡，寇来不得上。","一朝变起望夷宫，不及思旃曾技懩。"]},{"t":"述实录","f":"七言古诗","c":["承天圣祖开天业，四海为家尽臣妾。","规模宏远古无比，统绪岂惟垂万叶。","朅来海水不扬波，向见灵河已清澈。","除天所覆乐心戴，愈见人情皆感切。","折冲猛锐尽陈力，骨鲠贞良咸就列。","恭行天罚攘搀枪，著就鲸鲵殊剪截。","列圣未出无名师，历世弥光先圣烈。","推亡固存非一国，迷不知时非俊杰。","世许青野食前言，不若犬偷及鼠窃。","诬天复敢拘行人，妄专狙诈誇明哲。","国犹摄生贵处顺，水背流时源易竭。","即今日削尽疆场，其势得无忧迫胁。","若然仍不畏天威，曷异螳螂怒当辙。","未知其可将蛮触，相与区区较优劣。","武王问罪挥天戈，徵发诸军自崙碣。","翠华遥下五云来，辄报锦城氛祲灭。","扈跸貔貅三十万，争欲先驱埽妖孽。","搏熊攫豹捷飞猱，赴险蹈虚矜胆决。","纷驰传檄启途使，英荡辅之龙虎节。","悬崖万仞入云端，前马不行应气摄。","虹梁缥缈驾层霄，高兴动人殊可悦。","若非由蜀道登天，岂与飞仙得相接。","腾倾湍瀑翻惊涛，怒震横流还送折。","千岩万壑殷晴雷，捲起千堆万堆雪。","飞阁尤非地上行，剑门呼似天中裂。","壁立千寻冷翠屏，碧霞城拥清都阙。","振衣直上玉女台，下视烟尘望吴越。","五丁碎徙青黛山，万簇蚕丛乱堆叠。","金城虽包裹全蜀，胜负莫非由勇怯。","孰云无所骋骁骑，闭口势何劳捕舌。","天衷应未诱蚩萌，堪叹颛蒙与天绝。","宁知皇化如时雨，欲济迷津作舟楫。","会闻蓬阆朝真仙，箪食壶浆尽迎谒。","纷纷诸将无虚日，争奏归明争献捷。","旌门敕树受降旌，异致穷民遂安帖。","莫如天欲降何如，英猷一旦为虚设。","无雷东陊孤山峰，惊风西捲旂杆折。","龙桥忽焉悉中圮，夔鼓鼛然寻亦歇。","忍令飞驾鼎湖龙，持拔龙髯堕尘劫。","笛声唤得梦回来，梅梢犹印西窗月。"]},{"t":"密谷行","f":"曲","c":["命骁锐，为声援，选步骑，发畿甸。","号称一百万，一一皆精鍊。","旌旗虹乱渡桑乾，绚野如花陈组练。","移围布陈密谷口，吞敌出奇将伺便。","前拒避贾勇，中坚已受战。","天兵震天威，不异弄雷电。","先驱游击队，势若风云变。","雕鹗横秋空，奋翼鸷鸡犬。","斯须跆藉尽八九，终了不曾还一箭。","永安宫，大安殿，方待凯旋回赐宴。","唯有孤臣鬓成雪，缘底眉头殊不展。","智谋士见未然事，窃叹终皆非所辩。","堪怜当日金源氏，谁编良将忠臣传。"]},{"t":"蜀道有难易","f":"曲","c":["有言蜀道难，有说蜀道易。","难于上青天，易于践平地。","说易有所媚，说难有所激。","君曾不见与前修，折衷谁秉江山笔。","我来高蹈仙人踪，控御遗风纵游历。","连云气象霸图中，险阻形胜限疆域。","黑龙冲断万层山，骇浪轰雷恣奔击。","攒峰叠嶂冷云閒，绵亘倚天骈翠壁。","飞梁架云栈，势欲跨南北。","虹桥络河汉，鸟道挂空碧。","历其天险，临其峻极。","望舒按节，阳乌敛翼。","拟循云路趋鹏程，仰天直上青云梯。","蹑空且何异登仙，但觉日月行寝低。","终踰绝险得驰骤，骤步娲皇补天石。","微茫一径通烟霄，攀缘更上苍龙脊。","弥旬霖雨秋，行潦迷原隰。","岂不虑蹉跌，路歧多垫溺。","一闻漫天名，心寒已如失。","况复壅大道，与道为通塞。","无虑千筹将万计，智推力引方行得。","请设漫天前后论，蜀道一言或可毕。","未应难于上青天，飞阁递连通利走，名趋日夜往来何络绎。","不应易于践平地，栈磴缺寻引天荒，地老萧条断绝人声迹。","致令振古豺狼心，曾不祈天睹一掷。","自蚕丛且稽代谢，几人恃险曾终吉。","适足笑王公，设险以守国。","在德不在险，昭然如白日。","上青天，践平地，始可与之言其道难与易。","行路之难，难于上青天，蜀道之难，若比行路是平地。","出处虽然全在人，世路不能无险易。","畏途岂可比青天，誓铲漫天作平地。"]},{"t":"送杨子阳南还","f":"七言古诗","c":["鞭催瘦马出龙庭，白酒一杯送子行。","山头积雪寒皎洁，风物凄凄伤别情。","穷庐冰凘结吟砚，行人欲去愁展转。","功名入手头未白，世态浮云几千变。","何如有酒且高歌，百岁风光如过电，人生几度春风面。"]},{"t":"送玄之","f":"七言古诗","c":["东风二月吹和林，绿杨庭院空深沈。","整襟危坐罢舜琴，时听百鸟自在吟。","泠泠流水漱寒玉，半天萧飒松风音。","呼童为我金波斟，悠然一笑忘古今。","书斋尽日无人到，门掩落花春自老。","裴回杖履夕阳閒，回首春风乂衰草。","长安远客来紫宸，红尘满面初相亲。","挑灯风雨秋夜永，诗成落笔愁鬼神。","纵横论议小天下，当时谁谓秦无人。","一朝别我出祁连，黑山风雪十月天。","分襟执手小溪边，何时客床相对眠。","他年乘兴游京洛，诗酒无寒金谷约。"]},{"t":"送张敬叔","f":"曲","c":["去年见君瀚海东，苍松郁郁山重重。","今日送君之镇阳，寒烟漠漠天苍苍。","休叹萧萧行路难，两袖春风衣锦还。","二年两度客天涯，离合都无咫尺閒。","一尊白酒羡君侯，入手功名正黑头。","今年旱蝗民切痛，赋税须知有轻重。","一生富贵将几何，西风吹破邯郸梦。","自愧趋凤池，空有别离诗。","红尘无处避，扰扰心如醉。","何时高隐旧林泉，卧看人閒等儿戏。"]},{"t":"送人还镇阳","f":"曲","c":["云黯惨，风浩荡，故里风光空想像。","寒馀三月索貂裘，冻崖冰雪三千丈。","天淡淡，路茫茫，送君万里还镇阳。","杨花点点山城雪，啼鸟一声春昼长。","多离别，少歌笑，功名催促行人老。","玉箫吹断碧云寒，梨花寒食空过了。","君不见洛阳楼观今芜荒，梧桐叶落秋风凉，寒波寂寂山苍苍。"]},{"t":"摘阮行呈吕西冈","f":"七言古诗","c":["西冈老子古郑客，洒落心胸如李白。","或歌或啸或吟卧，万壑清风松下座。","呼童取得古锦囊，月魄囊中暗惊堕。","制度风流特奇绝，韵高不许俗人别。","试问先生是何物，云是阿咸葬时物。","英雄无限俱为土，如何此物传今古。","寥寥千载阿咸志，凭谁写出阿咸意。","悠然抱此明月腹，林下溪边时一曲。","十三玉柱秋蟾净，指底松风四弦泠。","大弦乌乌纯且雅，小弦切切清且劲。","秋高千穴寒泉瀑，露滴铜盘碎金玉。","千岩夜雨猿鹤悲，半夜西风鬼神哭。","物奇不肯人閒住，变作孤鹤上天去。"]},{"t":"长笛续短笛引","f":"七言古诗","c":["长笛短笛有指的，清浊有气亦有质。","李谟吹笛动长安，㝢内竞推为弟一。","笛声断绝续者谁，得许云封继其迹。","落梅宛转折柳声，不止飞砂将走石。","石裂云穿天亦惊，哈龙许云封怨笛。","云封烟锁不可开，直至如今吹不得。","有客手把昭华琯，未应旷代无人识。","什袭天然希世珍，尤当祇自私珍惜。","会须奇宝吐奇声，邪秽气随声荡涤。","静寻白雪引流风，拟写幽情聊自适。","遂据胡床弄秋月，萧条万籁沈凝寂。","凡奏一叠十二节，每发一声累九息。","流韵寥亮入太清，袅袅馀音游八极。","但闻天外鸾凤鸣，岂知海底鱼龙泣。","高迁亭化为灰烬，平阳坞久生荆棘。","揄扬天下之至音，非为俗聋惊结习。","伶伦嗟咏愿从事，列和怅然寻屈膝。","武昌老人请易业，洞庭老人还自失。","欲俪清歌妙入神，惜无李白生花笔。","孰知时尚紫云回，屡变新声延化日。"]},{"t":"天祐行","f":"曲","c":["魏创纪勋观，齐崇嘉德楼。","忽名天祐旌功阁，图写朱三在上头。"]},{"t":"战扼狐","f":"曲","c":["龙旂天上来，神兵落天阙。","问罪下中原，先有扼狐捷。","勍敌四十万，一何争勇决。","冲锋竞突刃，奋不待成列。","矢雨注，鼓雷叠，长兵尽，短兵接。","势霆击，天柱折，声海振，地维绝。","烈日照雪霜，几何不殄灭。","若是数百陈，然后成帝业。","信道守天元不易，圣统在垂千万叶。","敢忘开国缅良难，太祖新征战时节。"]},{"t":"五禽言","f":"曲","c":["我爱五禽言，味之殊有味。","不唯由此知物情，更是分明见天意。","大麦孰簸箕漏，伤时节，感农叟。","麦饭孰即快活，祛顑颔，略契阔。","提葫芦沽美酒，绕山溪，占花柳。","烧香拨火，愿言康且寿。","不如归去，莫饶舌，只合吞声牢闭口。"]},{"t":"放雁词","f":"曲","c":["御芦远避驾鹅声，人閒多避海东青。","冥飞休近双凫游，恐因误引到天明。","稻粱足，罗网轻，湖海多洲汀。","太虚无阂且何慕，鹦鹉玉笼笼下生。","与尔同六翮，好去恣飞腾。","若期寥廓求希有，必欲翱翔从大鹏。","宜审遥弓鸣，勿为虚弦惊，古来惟有一更盈。"]},{"t":"采莲曲","f":"七言律诗","c":["锦云承露珠盘冷，玉女佩环鸣玉井。","凝歌声入天镜来，兰桡扰碎蓬壶影。","弄香浮叶一何繁，翠盖霞幢不齐整。","可是芳心空自苦，淩波无梦惟烟景。"]},{"t":"长想思","f":"七言律诗","c":["燕子不来花著雨，莺声巧作烟花主。","满庭重叠绿苔斑，斜倚栏干臂鹦鹉。","清渭东流剑阁深，不知消息到如今。","相思前路几回首，一夜月明千里心。"]},{"t":"壶天园歌","f":"曲","c":["三十六洞天，七十二福地。","共春长在一壶中，尽可浮游与沈醉。"]},{"t":"乾海子","f":"七言古诗","c":["沙葱焦枯沙蓬乾，海子乾枯龙子殚。","顾非海变桑田日，如何一旦无涓滴。","琴高控鲤游何许，好探麻姑问消息。"]},{"t":"纪梦","f":"七言古诗","c":["衰草淡烟迷故垒，情思迢迢似流水。","关山目断雁声沈，几曲阑干闷独倚。","倚兰还忆早春时，款款东风绽桃李。","青春如昨岁云莫，大抵人生如寄耳。","如何携酒对明月，一笑红尘等白蚁。","归来梦蝶恼庄周，蝶去悠悠几千里。","吟哦犹在月明下，诗就清欢未能已。","举手欲折桂枝去，行入青天广寒里。"]},{"t":"松声行","f":"曲","c":["水深深，山重重，前溪后岭万苍松。","我来秋雨霁，夜宿深山中。","霜寒千里龙蛇怒，岩谷萧条啸貔虎。","波涛漾漾生秋寒，碧落无云自飞雨。","珑珑兀兀惊俗聋，馀韵飘萧散碧空。","悠然策杖出门去，方知万壑生清风。","清欢一夕无今古，句引幽人风雅句。","那堪更被山头月，团圆挂在青松树。"]},{"t":"和汉臣秋月海棠","f":"七言律诗","c":["魂黯马嵬西去路，当时生被春风误。","嫣然犹自带馀醒，贪睡那能慰迟莫。","难写花仙旧所思，褪青愁雪淡胭脂。","黄昏庭院潇潇雨，更是梧桐叶落时。"]},{"t":"大川行","f":"曲","c":["屯云黑色日将莫，晦明挥霍雨如注。","水声夜半摇匡床，平旦出门吁可畏。","盘涡溔瀁天边旁，悍流汹涌行中央。","日中雨复绠縻下，沟塍水跃皆浑黄。","黑风拗怒雷击地，浪头起立三尺强。","杈枒老木根株拔，崚嶒古屋椽桷裂。","快马万蹄迸突而凭淩，灵龟百面澒洞而砯砰。","锐兵鏖战城栅倒，猛虎嗥吼崖谷崩。","旁观气夺目力眩，濒流上下俱不宁。","升高避害叫舟楫，篙工倚柂不敢行。","寂寥向晓颇衰落，断霞返照回新晴。","鸟飞不尽天界阔，苍烟淡淡山青青。","衔杯引满幸无恙，收召魂魄犹屏营。","往年秋水沈半壁，阖门九死得一生。","今日思之痛方定，一见洪波心震惊。","吾闻山挟河回冲底柱，东峡江盘束滟滪。","鱼龙百怪家其中，风涛暴横无终穷。","小溪常时清且浅，漪涟不动平于板。","浅津可涉涉可梁，一旦沸腾能漭茫。","传闻溃渱山裂破，黑蛟夜出作奇祸。","抉崖走石势力粗，十家六七无空庐。","百年枯冢尚漂泊，变生仓卒人为鱼。","君不见去年四月不雨至七月，涧溪一线皆断绝。","川居人曾死于暍，山居人今死于溺。","下田黄尘曾蓬勃，高田白沙全障没。","呜呼灾变何其频，剿民之命谁肯任，苍天苍天实照临。"]},{"t":"十四夜月","f":"曲","c":["秋风滚地来，云捲河汉净。","遥观东海底，飞出黄金镜。","虽未十分圆，桂魄明且瑩。","停杯对清辉，信笔成新咏。","慇勤举杯属姮娥，休阻南楼夜来兴。"]},{"t":"夏夜对月","f":"七言律诗","c":["斜阳楼阁西风里，暑气著人难睡起。","觉来厌暑登东楼，月明如昼天如水。","金波漾漾流无声，中秋月好常人情。","青天休使浮云蔽，不是中秋月也明。"]},{"t":"谨上尊大人领省","f":"曲","c":["驱驰半世谁能晓，一点丹衷天可表。","中原不忍万民疾，肯羡蜗蝇利名好。","桑田晚见白蘋洲，天上人閒无限秋。","笔头横埽千人军，词源倒捲银河流。","閒来高卧烟霞里，笑看浮生等白蚁。","高歌一笑回东风，春满漫山桃与李。","华堂寿筵张，再拜献寿觞。","试看南山松柏姿，岁寒依旧色苍苍。"]},{"t":"仰祝尊大人领省寿三首 其一","f":"七言绝句","c":["帐前惊报天子来，临车下马无疑猜。","攀车引袂呼不起，齁齁酣寝声如雷。"]},{"t":"仰祝尊大人领省寿三首 其二","f":"七言绝句","c":["风云千载际会秋，堂上严君正黑头。","君王一顾闻天下，春满中原四百州。"]},{"t":"仰祝尊大人领省寿三首 其三","f":"七言绝句","c":["苍苍松柏贯四时，造物儿童元是私。","戏綵高歌献寿卮，寿卮愿约乾坤期。"]},{"t":"哭尊大人领省","f":"七言律诗","c":["孤儿泪眼空流血，一夜不知浑白发。","宝灯轮毕新记成，梦断疏钟吼残月。","白云隐隐入青冥，生死悠悠两长诀。","人閒天上父子情，遗愤有身终尽雪。"]},{"t":"瑞井行","f":"曲","c":["赤子半入井，宁无恻隐心。","急走掣其足，啼号嗄以喑。","其亲即偕来，翕然集四邻，将谓相谢不世恩。","忿呼恚诘渠何人，令我儿哭声酸辛。","中心自誓救颠坠，孰顾若辈怨且嗔，君子谋道不谋身。"]},{"t":"去妇怨","f":"七言律诗","c":["最苦人生生别离，匆匆轻别几时归。","紫箫吹落燕南月，丽泽门开马似飞。","雨晴不定云来去，老雁叫云云不住。","琵琶拨尽断肠声，断弦声断秋云莫。"]},{"t":"寄赵虎岩吕龙山","f":"五言律诗","c":["年来缘底事，不复出柴关。","兀兀千杯酒，萧萧两鬓斑。","月明河汉淡，天阔水云閒。","目断故人远，去鸿犹未还。"]},{"t":"寄高仲杰","f":"五言律诗","c":["一枕功名梦，半年风雨床。","地高秋易老，人去夜偏长。","悲赋伤鹦鹉，哀琴怨凤凰。","晚风吹落日，明月满寒塘。"]},{"t":"寄人","f":"五言律诗","c":["空翠扑晴影，轻黄著柳枝。","春风恋游子，浑似纵游时。","除醉更无事，忆君方有诗。","如何一片月，两地照相思。"]},{"t":"送元遗山行","f":"五言律诗","c":["燕北秋风起，幽花满地开。","既邀今日别，合道几时来。","白玉烟沈阁，黄金草暗台。","不须伤老大，珍重掌中杯。"]},{"t":"送李敬斋行","f":"五言律诗","c":["一代文章老，素车归故山。","露浓山月净，荷老野塘寒。","茆屋已知足，布衣甘分閒。","世人学不得，须信古今难。"]},{"t":"送完颜奏差行","f":"五言律诗","c":["君侯诣关日，款曲为慈亲。","故国少知己，旧山多逸民。","林园随分雨，天地自然春。","四海满桃李，惜花无一人。"]},{"t":"送正夫行","f":"五言律诗","c":["岁穷风景恶，萍梗客天涯。","咫尺辞兰省，优游出凤墀。","霜寒笳韵切，天远雁声迟。","瘦马长途晚，凝云雪欲垂。"]},{"t":"春日怀赵超然","f":"五言律诗","c":["万里故乡梦，五更残月钟。","去鸿书断绝，归燕语朦胧。","流水艳春态，好山呈晓容。","是谁将怨笛，吹断绿杨踪。"]},{"t":"寄郭隐君辅之","f":"五言律诗","c":["寄傲人閒世，潜真计未疏。","鸟行恬豹隐，惊食澹鹑居。","座列清谈客，门屯好事车。","不应驰素谒，坚待偃波书。"]},{"t":"秋夜对月赠唐臣","f":"五言律诗","c":["寒水摇空碧，西风满一琴。","孤光万家月，一寸百年心。","白雁惊残叶，青霜急乱砧。","故山休挂梦，无地可投簪。"]},{"t":"客中寄怀李先生九山居士","f":"五言律诗","c":["相忆复相忆，登临百感生。","河山分野色，风雨混松声。","白雁书秋思，苍苔篆古情。","如何千万里，独自计归程。"]},{"t":"晚集瑶华殿","f":"五言律诗","c":["月浸瑶华殿，云垂素女帏。","水晶帘半捲，火玉烛交辉。","紫气游清晏，休光下太微。","不知留帝所，疑执化人衣。"]},{"t":"春日即事","f":"五言律诗","c":["迟日照青春，游风荡紫宸。","雪霜无气力，桃李有精神。","幽思平欺酒，閒愁自避人。","忘机殊不恶，鱼鸟看来驯。"]},{"t":"泛太液池","f":"五言律诗","c":["烂纵飞龙驭，凝神入醉乡。","烟霞生缥缈，丝竹袅微茫。","蒲剑割秋水，荷盘倾夕阳。","莫轻年少日，青鬓易惊霜。"]},{"t":"伯哩行","f":"五言律诗","c":["胜气横千里，欢声洽万夫。","虎牙为后拒，犀首是前驱。","金练鸦光队，银枪雁子都。","率然乘伯哩，二战下崲峹。"]},{"t":"老将","f":"五言律诗","c":["结发究韬略，驰驱四十年。","长征秦五岭，苦战汉三边。","万死奋不顾，一生今幸全。","云台无住处，何日上淩烟。"]},{"t":"平南将","f":"五言律诗","c":["江淮平圮裂，原不事梯冲。","锐气吞坚阵，威声挫战锋。","高昂地上虎，王浚水中龙。","讵可同年语，论功与定封。"]},{"t":"南征奏捷","f":"五言律诗","c":["宸算将雄断，天然是美谈。","一征平漠北，再举下江南。","须不闻漂杵，何曾见溺骖。","元和歌圣德，恐未免怀惭。"]},{"t":"西征","f":"五言律诗","c":["白首征西将，封侯尽未贪。","远离穷发北，深入不毛南。","笑解重围困，威延转战酣。","若须求虎子，虎穴是当探。"]},{"t":"闻北耗诏发大军进讨","f":"五言律诗","c":["护军承诏日，骠骑佐轻车。","投豹韬攘恶，教龙钤辟邪。","除狼还得虎，养虺竟成蛇。","致使云台将，如云过涿邪。"]},{"t":"经扼狐岭得胜口会河战场","f":"五言律诗","c":["乌兔纵飞步，急于寒女梭。","扼狐名好在，得胜事如何。","暮雨连芳草，秋风捲素波。","战尘如可洗，当与侍中过。"]},{"t":"居庸关","f":"五言律诗","c":["秀拔延天险，寒盘万古根。","东西躔日月，南北限乾坤。","影落梅山冷，气摇星斗昏。","如何战尘下，荆棘暗重门。"]},{"t":"仙居亭","f":"五言律诗","c":["意匠惊难状，天然醉饮图。","两行风外柳，一册枕边书。","云锦薰沈水，莺簧脱串珠。","烟光将胜概，特贮在仙居。"]},{"t":"题虚白斋","f":"五言律诗","c":["可待留灵锁，方期得驻颜。","久虚生白室，长启扣玄关。","放浪形骸外，逍遥天地閒。","要当知雾豹，依旧在南山。"]},{"t":"书后堂壁","f":"五言律诗","c":["放浪形骸外，寄乡杯酒中。","催归有情鸟，促织可怜虫。","落日隔疏雨，断云垂渴虹。","弋人何所慕，霄汉点冥鸿。"]},{"t":"迎风馆","f":"五言律诗","c":["涤暑迎风馆，雄风袭玉扉。","云开天乙网，霞捲羽人衣。","倒景摇清禁，飞烟拥翠微。","泛阑将转急，须更入罗帷。"]},{"t":"司春园","f":"五言律诗","c":["地偏饶胜事，花事迥标奇。","春自长须在，人谁尽得知。","笑宜教捧腹，醉不解攒眉。","未那司春子，腾讥释二疑。"]},{"t":"雪香亭月下偶得名酒径醉为赋","f":"五言律诗","c":["琼露融云液，金泉涌月波。","带花浮绿蚁，和月卷红螺。","夜色依香雪，春容动绮罗。","是须轰玉笛，倚弄玉龙歌。"]},{"t":"拟西昆体后阁","f":"五言律诗","c":["夜枕雨声细，晓窗花气浓。","玉尘挂秋月，绣幕生春风。","藻井翠盘凤，画阑金走龙。","上名是何物，只合付儿童。"]},{"t":"读新乐府集","f":"五言律诗","c":["揽尽江山秀，珠玑咳唾新。","艳浮天上锦，情动月中人。","花鸟音容冶，风云气象频。","郢歌将白雪，憔悴对阳春。"]},{"t":"秋闺","f":"五言律诗","c":["供给深闺怨，秋声又捣衣。","鸳鸯不独宿，燕子自双飞。","尘暗芙蓉帐，风寒翡翠帷。","驰心属明月，将此照金微。"]},{"t":"春晓月下观白牡丹","f":"五言律诗","c":["小立犹痴睡，凝情出翠笼。","玉盘承晓露，金镜挂春风。","岂为素娥妒，不呈青帝功。","万花推弟一，谁更忌专宫。"]},{"t":"咏雪二首 其一","f":"五言律诗","c":["楼晓倚阑干，天低欲压阑。","削冰封岳色，飞席下云端。","风阵迟寒夜，星铓摇夜寒。","岭梅应见怨，何惮一来看。"]},{"t":"咏雪二首 其二","f":"五言律诗","c":["日淡隔云幕，地虚铺雪毡。","捲帘看不见，如画旧山川。","岂忆三杯酒，能回六月天。","一声何处笛，吹裂野梅边。"]},{"t":"圆福院竹","f":"五言律诗","c":["虚心虽涉世，贞节自孤坚。","翠梢挂明月，锦绷披紫烟。","岂无仪凤日，别有化龙年。","玉质捎云里，唯须著列仙。"]},{"t":"答座客","f":"五言律诗","c":["千红将万紫，剪染尽冰蕤。","莫晓谁施巧，惟春自出奇。","向阳花易发，伴老病难治。","若得如人意，除天是国医。"]},{"t":"调人幽居","f":"五言律诗","c":["瑟瑟苔封径，萋萋草暗阶。","莲舟浮太乙，玉笛喷洪崖。","巾漉糊涂酒，炉煨榾柮柴。","莫将千古计，取次却沈埋。"]},{"t":"贺人飞泉幽居","f":"五言律诗","c":["万斛惊珠冷，银河落翠微。","自歌还自舞，谁是复谁非。","高鸟知何处，浮云去未归。","好风将落叶，著意认柴扉。"]},{"t":"倦夜","f":"五言律诗","c":["展转延清漏，开帘纳月光。","西风恋残叶，终夕伴啼螀。","静柝沈蛮徼，疏钟撼客床。","六龙应振辔，飞日上扶桑。"]},{"t":"无何狂醉隐三首 其一","f":"五言律诗","c":["无何狂醉隐，慢訑更痴蒙。","虽涉人间世，殊参塞上翁。","只须推倚杖，不必论穷通。","且把无边事，横陈在酒中。"]},{"t":"无何狂醉隐三首 其二","f":"五言律诗","c":["无何狂醉隐，拙直更疏慵。","花鸟閒情外，江山醉眼中。","涉江搴薜荔，缘木采芙蓉。","待把人閒事，从头说化工。"]},{"t":"无何狂醉隐三首 其三","f":"五言律诗","c":["无何狂醉隐，耕适是生涯。","驯护能言鸟，调笼解语花。","不应抛蝶梦，须与趁蜂衙。","谁佐杯中酒，仙人萼绿华。"]},{"t":"穷庐篇","f":"五言律诗","c":["巢燕年年客，山河日日新。","窗分一镜晓，门掩满庭春。","栖鸟羁笼影，行蜗游壁尘。","故园虽好在，楼观几荆榛。"]},{"t":"寓居灵州北村","f":"五言律诗","c":["野色荒烟暗，氛霾昼影昏。","客情纷若絮，尘事乱如云。","杨柳春风渡，梨花暮雨春。","不如归去鸟，著意唤谁闻。"]},{"t":"双溪月下戏赠触热冲暴雨者","f":"五言律诗","c":["夐入清虚府，轻河漾月舟。","冰天通色净，水月杂波流。","雨横蚁兵溃，日熇山市收。","若然閒意况，原不到心头。"]},{"t":"戊申己酉北中大风","f":"五言律诗","c":["冲风回白日，飞砾洒青天。","富贵城西畔，珍珠河北边。","阳冰原不冶，阴火更潜然。","直澈龙荒外，萧条是野烟。"]},{"t":"过东山县有怀","f":"五言律诗","c":["忆昨惊尘下，肠回望眼穿。","计程虽信宿，恨别似经年。","自致青云上，谁来白月边。","万金游子信，空与梦牵缠。"]},{"t":"追悼大人领省","f":"五言律诗","c":["税驾知何处，仙游阅古今。","英灵千载气，松柏一生心。","白日空寒色，苍天更暮阴。","志终伸不得，遗恨海长深。"]},{"t":"春色浮山外","f":"五言古诗","c":["春色无高下，宁分泽与邱。","世间依旧好，山外若为浮。","桃李花争拆，池塘草自抽。","绿涵峰势合，红带烧痕收。","迟日千钟酒，东风百尺楼。","夜来甘雨足，溪谷已成流。"]},{"t":"立春二首 其一","f":"七言律诗","c":["东帝施恩似恤贫，严凝时节唤回春。","未知和气先归柳，便觉寒威不著人。","上苑三冬梅正发，和林五月草初新。","世閒公道惟春色，春色年来也不均。"]},{"t":"立春二首 其二","f":"七言律诗","c":["节物惊心若见催，一年还见两春来。","腊寒自向人閒尽，春色却从天上回。","乍暖柳条先易绿，向阳花树不难开。","高歌买断西城酒，更对东风尽此杯。"]},{"t":"春日寓怀","f":"七言律诗","c":["燕语鸾啼怯晚阴，蝶狂蜂乱更关心。","冥鸿空自运寒暑，骇浪为谁淘古今。","每纵思吟轻万户，但言眉笑抵千金。","闭门不出近十日，忽到水边春已深。"]},{"t":"三月和林道中未见草萌","f":"七言律诗","c":["不觉清明梦里惊，问人人道过清明。","须知上苑花飞树，谁信和林草未萌。","绿水归鸿空自感，淡烟啼鸟若为情。","翩翩瘦马荒山路，衰草斜阳正独行。"]},{"t":"西园春兴因赠雪庭上人兼简张公讲师","f":"七言律诗","c":["万丈虹霓络紫烟，笙歌清沸雨馀天。","满庭芳草翠如积，一洞碧桃明欲然。","流水引来梅坞底，春风吹到酒垆边。","散花唤起毗邪梦，从此无心号谪仙。"]},{"t":"清明","f":"七言律诗","c":["寒食清明失旧期，踌躇搔首日沈西。","风生杨柳鸦先觉，寒过梧桐凤不栖。","山色雪迷春意老，雁声云遏暮天低。","苏门二月春光好，好逐东风发马蹄。"]},{"t":"重和惜春诗韵余时经始西园","f":"七言律诗","c":["惜春情味旧情缘，依旧中情似去年。","怪得玉音殊郑重，想将花事易唐捐。","白莲已结为诗社，翠水唯浮载酒船。","谁谓惜花人老大，买花输得买山钱。"]},{"t":"谨用尊大人领省十六夜月诗韵","f":"七言律诗","c":["黄鸡白酒管弦和，一任浮生岁月磨。","银管题诗应远客，玉箫吹恨忆秦娥。","人言皓魄今宵减，我见清光依旧多。","一十二时争几许，人閒柰此世情何。"]},{"t":"中秋对月","f":"七言律诗","c":["银烛煌煌十二衢，冷金波浸酒仙居。","由来物外通明殿，只是人閒不夜珠。","玉女窗扉唯白晓，素娥庭院更清虚。","桂花香陌无尘景，全入壶翁碧玉壶。"]},{"t":"冬日即事 其一","f":"七言律诗","c":["征鸿南渡老年华，渐觉冬来眼界多。","寒雪狂风颤林木，冻云残照锁关河。","高低山势黄沙碛，远近人家白草坡。","极目碧天长万里，醉邀明月一高歌。"]},{"t":"冬日即事 其二","f":"七言律诗","c":["蜡栀五万酬鞭直，洴絖百金且食封。","萧散不萌争闹趣，真醇缪觊养生慵。","涤清研里憨凡笔，磨彻鉴中嚬窘容。","伤到玄冥潜春令，狐裘羔酒贮严冬。"]},{"t":"日南至","f":"七言律诗","c":["猎猎严风正酷寒，一阳潜动旧关山。","人情徒怨融和晚，天意何曾造化悭。","暗逐寒威归汉外，渐回春色到人间。","明年桃李知多少，莫把东风作等閒。"]},{"t":"谨用尊大人领省龙庭风雪诗韵 其一","f":"七言律诗","c":["登高何处是燕然，极目关山塞草边。","落日几峰寒带雪，西风一雁冷横天。","冬居冰谷赖酮酒，夜宿沙堤借草毡。","为向中州豪杰道，天涯如此过年年。"]},{"t":"谨用尊大人领省龙庭风雪诗韵 其二","f":"七言律诗","c":["冻折瑶琴三两弦，起来孤坐忆成连。","可堪此世成何事，了却生平莫问天。","门外共传三尺雪，帷中赖有四围毡。","遥思千古功名辈，回首西风不记年。"]},{"t":"九月道中遇雪","f":"七言律诗","c":["密密痴云晚自凝，飘零踪迹断蓬轻。","幽禽底事啼长咽，流水何缘浪不平。","清梦未回人换世，黄花应怨我寒盟。","故园回首肠堪断，雪满荒山瘦马行。"]},{"t":"途中值雪","f":"七言律诗","c":["不禁风色避穷庐，寂寞行人正半途。","日暮关河云黯淡，晚来天地雪模糊。","千山未霁寒尤重，一鸟不飞人更孤。","旅拨寒炉一尊酒，故人知我此情无。"]},{"t":"欲雪","f":"七言律诗","c":["痴云泄泄复溶溶，底事龙公睡起慵。","薄暮遥看岩岫失，夜阑空把斗牛封。","徘徊天外心无定，撩乱江头色正浓。","寄与西风莫吹散，梅花憔悴忆相逢。"]},{"t":"双溪书院对雪","f":"七言律诗","c":["宴处云华不夜庭，为餐琼蕊更谈经。","听随瑞叶风来处，看散天花酒半醒。","白凤羽毛寒荡漾，玉龙鳞甲战凋零。","倘非太素司光化，谁压惊尘与效灵。"]},{"t":"送贯彦从","f":"七言律诗","c":["淡烟衰草两无情，寒泻金波送子行。","可奈驰驱来瀚海，不堪牢落过清明。","半帘皓月人千里，满目春风雁一声。","瘦马鞭椎低塞日，数年江上雨初晴。"]},{"t":"送冯赟","f":"七言律诗","c":["北去南来牵利名，红尘鞍马老生平。","天涯海角长为客，薄酒新诗复送行。","秋早地高山改色，夜深风紧雁饶声。","起来细把归期数，今日凄凉弟一程。"]},{"t":"送安善甫","f":"七言律诗","c":["龙庭二月送君归，底事人生足别离。","幽鸟一声春寂寂，东风千里马迟迟。","烟迷故垒襟分处，月淡山城梦破时。","此去萱堂休忘却，坚持忠孝是男儿。"]},{"t":"送魏隐君","f":"七言律诗","c":["十年相忆不相逢，一日相逢意气同。","落落了无寒士态，堂堂浑有古人风。","雨寒秋泣黄华泪，霜重山涵碧树红。","岁晚可怜犹是客，素琴孤剑几西东。"]},{"t":"送诚之行","f":"七言律诗","c":["惆怅分襟北海西，悠然不觉泪涟洏。","自怜远地无朋友，思与君侯处别离。","万里风沙秋半后，一笼灯火夜深时。","相期老柏三千丈，不改淩霜傲雪姿。"]},{"t":"送子周行","f":"七言律诗","c":["衰草凄凄塞日斜，春风得意出龙沙。","南飞鸿雁三秋雪，东望关河万里家。","杯酌歧边浮竹叶，角吹陇上弄梅花。","征鞍迢递中州道，淡淡长空点暮鸦。"]},{"t":"送子华行","f":"七言律诗","c":["雁行飞尽暮云收，送子歧边酒一瓯。","远树深埋黑山雪，晚风寒索紫貂裘。","悠扬鼓角千岩月，惨淡关河万里秋。","寂寞归来回首处，几声山鸟语啾啾。"]},{"t":"送孟端卿","f":"七言律诗","c":["万里归来两鬓霜，百年间事也难量。","跳丸岁月无留计，画饼功名不可尝。","鸿断碧云空落日，尘飞沧海已生桑。","莺花未老春犹在，更对青山共一觞。"]},{"t":"送宁朔","f":"七言律诗","c":["说从薛烛授吹毛，从事孙吴与六韬。","应策腾空调赤电，惊弦裂石试乌号。","鼎鱼幕燕由西极，侵气游魂在北郊。","击惰捣虚原有策，必须先直取窠巢。"]},{"t":"送李稚川 其一","f":"七言律诗","c":["云来云去元因雨，花落花开总是风。","白酒尽堪骄富贵，青山只合傲王公。","从甘鸡肋功名后，已堕羊肠世路中。","为语屏山痴子弟，虎狼丛里逞豪雄。"]},{"t":"送李稚川 其二","f":"七言律诗","c":["一尊浊酒与君同，握手相随出帝宫。","牧笛唤回千里梦，秋风点破一飞鸿。","参横斗转关河月，山寂猿啼草木风。","酌别淡烟衰草路，飘零踪迹又西东。"]},{"t":"送人","f":"七言律诗","c":["是是非非尽自宜，掀然一笑且信眉。","休辞沈醉过终日，纵得再归来几时。","极浦遥山遗别梦，碧云流水寄相思。","伤心去国头如雪，憔悴春风对柳枝。"]},{"t":"送韩浩然","f":"七言律诗","c":["开怀尊俎笑谈倾，未暇论文君已行。","富贵涂亨渠易致，诗篇韵险我难赓。","已成倾盖金兰友，安用沾襟儿女情。","准拟秋深近归骑，一尊浊酒远相迎。"]},{"t":"送子文还家","f":"七言律诗","c":["道直如弦气吐虹，尽输心计静颓风。","倦蕲待诏留金马，遽乞还山命玉骢。","天幕几曾巢客燕，云罗终不挂冥鸿。","多思高谢人閒了，不似痴仙醉梦中。"]},{"t":"用西冈老人留别诗韵以赆其行二首 其一","f":"七言律诗","c":["健羡男儿得志秋，锦衣归去跃骅骝。","断肠南陌人何在，回首夕阳水自流。","故里得归真乐土，浮生无地不天游。","疲民正赖君侯手，莫把功名让黑头。"]},{"t":"用西冈老人留别诗韵以赆其行二首 其二","f":"七言律诗","c":["昔年冷坐渭河滨，独钓寒波绝路尘。","流水高山千古事，淡云微月一閒身。","祇知门巷无他客，唯有琴书是故人。","今日圣朝方大用，江山应助老精神。"]},{"t":"和子文留别诗韵以赆行","f":"七言律诗","c":["天涯牢落故人稀，与子论文真所依。","万里有行君有志，双亲无恙我无违。","愁如流水何时尽，身似杨花到处飞。","明日不堪离别处，高吟新句赠玄晖。"]},{"t":"西行留别诸人","f":"七言律诗","c":["绿杨飞絮草铺茵，到处春光随意新。","几个道傍留别客，万重山外远行人。","凄凉幽鸟唤残月，狼藉野花伤莫春。","酒薄无由求一醉，更堪归鸟过来频。"]},{"t":"留别诸友","f":"七言律诗","c":["还池亭上醉飞觞，春暖波閒怕夕阳。","高挂无弦云满地，一喷横笛水千塘。","槛依兰影香犹湿，帘隔泉声意自凉。","后会不知何处是，对床休避细商量。"]},{"t":"读甲子改元诏因叙怀留别诸相","f":"七言律诗","c":["忆昔东征去国门，黯然为别更消魂。","若图白首妻孥计，是负皇家父子恩。","中统始开新甲子，至元重整旧乾坤。","九州四海升平望，要竭丹诚翊至尊。"]},{"t":"早行","f":"七言律诗","c":["窗外寒鸡唱五更，翩翩征旆挂疏星。","百年身世情如梦，半纸功名醉不醒。","欲吐半吞残月淡，似连还断远山青。","莫教草草生华发，消得几回长短亭。"]},{"t":"发凉陉偏岭南过横山回寄淑仁","f":"七言律诗","c":["浮游汗漫和南陔，直指凉陉是九垓。","偏岭最饶秋色处，横山不出冷云来。","未须白雁传霜信，已早黄花带雪开。","想得玉滦河北畔，有人独上李陵台。"]},{"t":"近因北事和林亲故离绝途次云中先寄燕南一二知己","f":"七言律诗","c":["栖迟徙倚赋登楼，休想情怀似去秋。","著意不来看鬓脚，岂知何事在心头。","莫惊歌凤狂犹在，见说屠龙老更羞。","谁料一双痴醉眼，战尘西北望神州。"]},{"t":"寄西平","f":"七言律诗","c":["鼠偷狗窃敢炰炰，争信貔貅已缔交。","将叠连珠调鹊角，拟追逐日试蒲梢。","序移玉律阴风急，气应金商太白高。","惜别折冲尊俎地，莫容南牧越临洮。"]},{"t":"春寒代人有寄","f":"七言律诗","c":["睡鸭香消宝篆残，萧萧松竹雨声寒。","水当流去雁将尽，花未放来春已阑。","斜日多情送归鸟，碧云无迹问飞鸾。","不应凤女祠前月，只许吹箫独自看。"]},{"t":"春日和林寄赵虎岩吕龙山","f":"七言律诗","c":["年年芳草怨王孙，日日幽人独倚门。","踪迹飘零又寒食，别离滋味奈黄昏。","一楼风雨欺归梦，万里云山动客魂。","欲写相思寄双鲤，乱离春水雪消浑。"]},{"t":"春日寄怀魏隐君邦彦","f":"七言律诗","c":["满眼春风捲暮阴，五噫歌罢更沈吟。","十年万事没孤鸟，百念一时生寸心。","芳草不随莺燕老，好山依旧水云深。","遥怜野鹤高飞去，夜夜投栖何处林。"]},{"t":"登叠巘楼寄本庵粹中","f":"七言律诗","c":["江山不尽古今情，空写相思遍凤城。","满眼氛埃昏落日，一天寒色淡长庚。","吟魂岂为閒情断，别梦徒因往事惊。","早晚重来风雨夜，细倾肝胆话平生。"]},{"t":"寄岩翁","f":"七言律诗","c":["游子不来春草碧，忽闻啼鸟怨残红。","河声忽与回青断，山色还随落日融。","华屋烟霞箫管歇，凤楼城士酒杯空。","多应云鹤相将去，又在蓬邱弟几宫。"]},{"t":"寄李徵君","f":"七言律诗","c":["岂当容易慕陶潜，莫枉明时振废淹。","薄宦怀情虽自减，竦人声价为谁添。","雷霆威重休轻许，雨露恩饶可共沾。","纵是世无颜叔子，更宜学避鲁人嫌。"]},{"t":"寄国范昌龄","f":"七言律诗","c":["总道绸缪思好在，断无人迹继芳踪。","情亲便合称三凤，友爱何妨号二龙。","莫为鬓丝抽思绪，不将学海淬辞锋。","绿波烟草滦阳渡，独倚危楼到下舂。"]},{"t":"寄尹仲明兼简卢进之","f":"七言律诗","c":["别后相思拨未平，登高西望转关情。","林边残日没归鸟，天际断云飘晚晴。","久把功名为外物，拟将诗酒畅平生。","自从身世相忘后，万事人閒一唾轻。"]},{"t":"寄李道隐之和","f":"七言律诗","c":["竦诮驰声牧九州，覈玄心事傲王侯。","风情张日排巢父，霜气横秋拉许由。","腾笑务光何足比，献嘲涓子不能俦。","北山逋客幽栖地，可是英灵许再游。"]},{"t":"寄隐者","f":"七言律诗","c":["投老尝期谢草莱，有人怀抱待君开。","叩玄要给谈人口，虚白原宜养圣胎。","凤尾诺虽徵不起，鹤头书合召将来。","莫惊此会知何处，认取黄金是旧台。"]},{"t":"壬子秋日客舍纪事因寄家兄","f":"七言律诗","c":["判花歌鼓殷晴雷，露叶霜枝漾酒杯。","金水净穿深巷陌，玉泉浮动远楼台。","可堪白鹤将秋去，又著青云入梦来。","原上脊令何处所，不听游子咏南陔。"]},{"t":"责友人久不寄书","f":"七言律诗","c":["堆积离愁无奈何，年来俗态可堪嗟。","人情个个薄如纸，世事纷纷乱似麻。","燕子不来书谩草，雁行飞尽眼昏花。","而今试问风篷迹，海角天涯到处家。"]},{"t":"赠卢隐君","f":"七言律诗","c":["放情丘壑谢嚣氛，逸气翛然自不群。","捷径岂容留隐士，驾鸿方可是徵君。","独轮车辗岩边月，十角牛耕陇上云。","曾约华山分一半，如何犹不许同分。"]},{"t":"赠酒乡道隐李君之和","f":"七言律诗","c":["一自琳宫见锦囊，几回先爇玉蕤香。","醉乡更比乾坤大，仙境元饶日月长。","五柳先生陶靖节，四明狂客贺知章。","无为未必无遗恨，不列三千弟子行。"]},{"t":"春晚怀吕龙山","f":"七言律诗","c":["洞箫吹断柳花风，恨别苍苔满径踪。","幽梦已凭春领略，凝愁唯藉酒弥缝。","千山落叶沈残角，万壑归云入暮钟。","近说鬓毛浑白尽，可堪空忆旧音容。"]},{"t":"呈鹏南学士","f":"七言律诗","c":["妙龄特达冠群英，家世灯传白与清。","气压西山正开爽，学尊东鲁独精诚。","棠阴政简琴心古，瓜孰归来句眼明。","他日宴堂香一瓣，潜通玉烛两忘情。"]},{"t":"复次赵虎岩元韵","f":"七言律诗","c":["道直如弦气吐虹，几人臭味与君同。","西湖处士林和靖，东里先生吕本中。","举世是皆惊炙毂，有人应更惮乘骢。","阿谁狂直今如此，不是痴仙即醉翁。"]},{"t":"和光祖诗韵一首","f":"七言律诗","c":["西风望断碧云深，万里关河入俯临。","客思暗随愁共远，髯冰疑是老相侵。","霜鸿傍月传佳信，寒雪漫天拥衲吟。","十载因循归未得，飘零踪迹到如今。"]},{"t":"寄题一枝庵主人","f":"七言律诗","c":["消息盈虚合费辞，德人何虑复何思。","穷通不信无非命，贵贱由来定有时。","方欲自专齐物论，未知谁是大宗师。","击抟九万三千里，何异巢林弟一枝。"]},{"t":"送张寿甫尚书出尹河南","f":"七言律诗","c":["满路黄花照暮秋，旌旄绰约促行辀。","名卿均逸膺宸算，方牧分符耸士流。","翰苑文章饶雅趣，伊川风物冠中州。","明朝黄阁求元老，却恐纶恩妨胜游。"]},{"t":"燕市送客归长安故居","f":"七言律诗","c":["黄金台上望长安，何处青山是故山。","虹断桥梁分雨脚，露摇珠颗偃荷盘。","归心暗逐飞鸿尽，病眼空将倦鸟还。","芳草不随游子去，日斜烟淡倚阑干。"]},{"t":"送米君周还镇阳","f":"七言律诗","c":["驰驱万里赴龙庭，今日还归出帝京。","一夜雪寒添客恨，三秋风物动离情。","临歧把酒君离别，信笔题诗我送行。","贱子一言君记取，得无青眼顾书生。"]},{"t":"枕流亭","f":"七言律诗","c":["振濯尘缨奠枕流，桃花源上玉溪头。","春风来领长欢伯，和气追陪独醉侯。","童子只知除害马，庖丁原不见全牛。","痴仙事业依然在，甚识人閒有棘猴。"]},{"t":"题枕流亭","f":"七言律诗","c":["窃期摛藻掞天庭，閒作篇章抒下情。","殊喜濂溪爱莲说，未甘桑苧著茶经。","逍遥方外无为业，整顿人閒不朽名。","缘洗尘嚣耳中事，举家移住枕流亭。"]},{"t":"池亭用前韵","f":"七言律诗","c":["推穷理窟叩真庭，探索天心见物情。","忆昨冥心捕蛇说，笑今凝思相牛经。","未妨招隐教投迹，不信潜夫肯著名。","爱杀清风与明月，肯随人意到池亭。"]},{"t":"秋日避暑尘外亭","f":"七言律诗","c":["软红尘外水云乡，隐映双溪避暑庄。","雌霓连蜷应计雨，雄风回穴自输凉。","年光变弄蒲萄色，天气经营菡萏香。","只就北窗花柳下，岂妨高卧傲羲皇。"]},{"t":"泊白鱮江尘外亭高道士携琴相访","f":"七言律诗","c":["引回柔橹款亭皋，宛驻灵槎泛雪涛。","尘外水沈薰菡萏，瓮头春绿涨蒲萄。","红螺山色秋尤健，白鱮江声晓更豪。","安得投簪招隐士，携琴寒玉从琴高。"]},{"t":"饮方湖菊州尘外亭","f":"七言律诗","c":["三径虽然已就荒，菊州犹在水中央。","不愁尘外仙无路，窃喜花前醉有乡。","倦鸟也知人去就，狎鸥原识我行藏。","浮游种种真滋味，更索谁教仔细尝。"]},{"t":"题四娱斋 其一","f":"七言律诗","c":["门掩春壶安乐窝，纷纷俗事奈人何。","须凭欢伯攻愁阵，自有桐孙伏鬼魔。","遣兴色丝何摆落，尘怀黄奶解消磨。","拍阑一笑遥天碧，付与儿童学揣摩。"]},{"t":"题四娱斋 其二","f":"七言律诗","c":["雪满兰窗雾满阶，恍疑身世在瑶台。","琴馀细嚼陶潜句，书罢深倾李白杯。","流水净拖飞练去，好山晴与翠屏开。","百年乐事能多少，何必更歌归去来。"]},{"t":"题四娱斋 其三","f":"七言律诗","c":["细细清风染绿槐，丝丝疏雨洗黄梅。","山围楼阁周遭碧，花绕阑干次弟开。","日落青天见萤火，云归沧海听蚊雷。","知音不是王夫子，谁为陶潜送酒来。"]},{"t":"纵游壶天园","f":"七言律诗","c":["水摇晴影漾楼台，台上花前载酒来。","杨柳不胜金缕瘦，海棠空自锦云堆。","梦随峰蝶寻春去，兴入烟云尽处回。","欲纪所思吟不得，却谁先篆满苍苔。"]},{"t":"夜宴壶天园","f":"七言律诗","c":["门掩山居不记重，紫霞容与贮春风。","玉箫赴节徵双凤，兰烛飘香拥六龙。","织女下时星自落，姮娥来后月长空。","始知不死琼田草，唯在壶中罨画峰。"]},{"t":"春旱郊园诸花犹盛醉归憩槐盖阴下","f":"七言律诗","c":["渴雨苗虽未发荣，可无芳意慰坤灵。","草缘近水堤边绿，柳绕新池岸上青。","花匠斗供春制度，曲生专与我调停。","且倾翠盖谁如故，依旧槐阴满后庭。"]},{"t":"题缙云山五湖别业","f":"七言律诗","c":["为爱烟花可挂怀，并供幽思上灵台。","缙云直拔空青起，落水横吞野翠来。","欲界曲随仙境变，好花争映画屏开。","终期尽把开桃李，就此名园胜地栽。"]},{"t":"五湖别业新图","f":"七言律诗","c":["除却五湖烟月外，只容春色入重关。","可怜东国兔三窟，不见南山豹一斑。","独醉轩昂花柳下，无尘亭立水云閒。","谁期造物输原力，更许清风恣往还。"]},{"t":"小隐园拟乐天","f":"七言律诗","c":["吏隐厅西小隐园，小塘池在卧房前。","指垂杨柳为烟客，认白莲花是水仙。","歌案柳枝翻折柳，醉斟莲叶倒垂莲。","不烦驰誉丹青笔，胜醉仙图是处传。"]},{"t":"兰畹见和鄙语无尘亭复用前韵","f":"七言律诗","c":["草色连阶草满庭，且图荣悦野人情。","任呼醉隐为书簏，要识书淫已醉经。","高卧莫疑将索价，浮游须不近沽名。","祇消卷迹嚣尘外，寄傲空凉水上亭。"]},{"t":"春晴极寒登池楼书事","f":"七言律诗","c":["晴影深寒碧玉流，郁香兰芷暗芳洲。","冻侵莺舌声全涩，风恋花枝颤未休。","目断野烟横极浦，心悬明月入高楼。","应须买尽人间酒，更不令寒画一筹。"]},{"t":"和林春舍叙西园前宴招一二友生重饮","f":"七言律诗","c":["楼阁参差翳紫烟，佳人情重惜流连。","月明杨柳春风夜，寒食梨花暮雨天。","将谓浮云寄浮世，岂知流水是流年。","殷勤不醉花前酒，强作守钱奴可怜。"]},{"t":"清明前一日月夜对酒招季渊饮","f":"七言律诗","c":["醉乡吟社两厌厌，寒食清明事已兼。","春计政侵云子酒，月华不隔水晶帘。","幽兰香结成凝阵，宝篆烟空尽未添。","连璧胜游心赏在，莫轻倾盖一掀髯。"]},{"t":"忆双溪","f":"七言律诗","c":["兰州怀抱玉溪分，龙自深蟠草自茵。","楼观几经浮世换，河山依旧主人新。","莺花有意长留我，桃李无言自好春。","想得多情怨迟暮，不应终老马牛尘。"]},{"t":"春日西园招雪亭","f":"七言律诗","c":["暖日浮云漾绿波，画阑风静好经过。","护花飞蝶来呈舞，恋柳啼莺自献歌。","妨物性疏轻物议，惜春情重奈春何。","流年不为朱颜息，莫厌尊前笑语多。"]},{"t":"匏瓜亭二首 其一","f":"七言律诗","c":["一壶天地备菟裘，应结壶翁物外游。","田仲尽当多屈毂，惠施何得应庄周。","岂容五石为无用，好办千金预为酬。","匏落纵甘成弃物，世途元更有中流。"]},{"t":"匏瓜亭二首 其二","f":"七言律诗","c":["拟挹春风颍水滨，坐忘颜陋谢嚣尘。","素知居士非田仲，只识幽人是卞彬。","尽办仙家方外地，径输花坞瓮头春。","岂为无口辞供济，好虑为尊与问津。"]},{"t":"缙云五湖别业书事","f":"七言律诗","c":["纵恬高蹇徇真愚，元也中心怯畏途。","共命不能同好恶，寄生那有异荣枯。","为营独醉成三窟，方引双溪入五湖。","就著鹤头书背上，已私宏景两牛图。"]},{"t":"西园席上招雪庭裕上人","f":"七言律诗","c":["山光摇荡入帘栊，酒漾歌云暖玉融。","烟柳翠涵深院雨，露花香湿满楼风。","自从愁阵持降节，拟与诗兵纪战功。","借问飘零断肠客，为谁幽独卧莲宫。"]},{"t":"宴台","f":"七言律诗","c":["万象森罗动翠华，谪仙名擅地仙家。","忽疑羽化随青鸟，空记嵩呼隔彩霞。","休计露盘承玉屑，枉徵云液就丹砂。","两龙胜迹空流水，流尽临风野荠花。"]},{"t":"苍官台","f":"七言律诗","c":["谁赞君侯缔构功，尽收形胜压天东。","洪流下瞰朝宗远，叠嶂横陈堡塞雄。","凤阙凝眸云掩霭，鸡林指掌树冥濛。","髯龙似识登龙意，时摆寒梢弄晚风。"]},{"t":"郝侍中钓台","f":"七言律诗","c":["槎杌荆榛薙草莱，欲令无一点尘埃。","行歌正则行吟泽，坐啸狂奴坐钓台。","鸟道不冲天宇断，雁行横过海门恢。","黄花已为西风瘦，更对凝霜鬓影开。"]},{"t":"独醉亭","f":"七言律诗","c":["澡雪精神住福庭，放言须不逆时情。","推移殿最修花史，分别贤愚著酒经。","爱酒爱花俱有趣，独醒独醉两虚名。","祇知仰挹清风处，万古心期是此亭。"]},{"t":"书三乐轩壁","f":"七言律诗","c":["虽任无为定是非，更须教勒北山移。","笔驱造化天何补，身质声名道不知。","见说丹心明似镜，忍将青鬓照成丝。","深根宁极如无待，越舍含华却是谁。"]},{"t":"醉书双溪书院醉经堂壁","f":"七言律诗","c":["自从天隐自然庭，愈觉嚣尘喷鼻腥。","可要洞研齐物论，更须深味洗心经。","独醒终了醒如醉，独醉那辞醉不醒。","列百圣贤真趣在，古人糟粕是螟蛉。"]},{"t":"宴玉津园","f":"七言律诗","c":["碧玉池塘翡翠堤，露轩飞檄拥璇题。","蝶迷芳径有时见，莺就绿阴深处啼。","不觉径来穿月窟，可能须待蹑云梯。","一壶春色长留在，尽寿吟山取醉泥。"]},{"t":"和林西园月台怀吕龙山","f":"七言律诗","c":["日薰花气暖徘徊，花影横斜入酒杯。","不见海棠春睡足，可怜江燕晚归来。","烟迷野色自芳草，水落石根空翠苔。","谁劝柳阴深且住，有人凝绝在高台。"]},{"t":"暮春登凌云台","f":"七言律诗","c":["水自长流莺自啼，雀来巢壁燕来飞。","红销歌殿夜棠瘦，绿暗妆台春草肥。","今日不知明日事，今人休笑古人非。","寥寥千古登临思，分付东风与落晖。"]},{"t":"凤凰山别业寄润甫儒医尤娴于摄生","f":"七言律诗","c":["湫隘嚣尘不可居，凤凰山岂厌潜夫。","无花不欲教为主，有草须堪更结庐。","元化唯珍五禽戏，通明殊玩两牛图。","莫惊独醉居无事，心醉镕经与著书。"]},{"t":"春园","f":"七言律诗","c":["胜事分明日月多，金莲川上爱凉蜗。","珍珠柳袅垂珠树，翡翠茵舒展翠莎。","虚白室常安乐土，软红尘不到行窝。","索教妆点新春色，且剩山花四五窠。"]},{"t":"独醉园对饮","f":"七言律诗","c":["独醉园中独醉翁，醒时还与醉时同。","祇因矫思原如矢，窃自修身更似弓。","无可奈何倚玉友，有何不可任崖公。","醉乡纵裂封侯地，且就擒奸莫论功。"]},{"t":"赠渔者","f":"七言律诗","c":["蜃楼鳌殿对柴扉，旋挽新荷补旧衣。","短笛有时浑落调，曲钩何计可忘机。","沧波万顷淡烟合，白雁一声黄叶稀。","回想渭滨人去后，夕阳空满钓鱼矶。"]},{"t":"赠仙音院乐籍侍儿","f":"七言律诗","c":["著名仙籍擅芳春，料理霓裳纪见闻。","欬唾随风落珠玉，笑谈倾坐播兰薰。","龙酣醉笛吟秋水，凤咽歌楼遏暮云。","唤起沈香亭上梦，海棠花睡月纷纷。"]},{"t":"听琴","f":"七言律诗","c":["恰弄歌珠引玉清，梁间早已暗尘惊。","风流回结行云住，激水延缘漱雾生。","只道绵驹殊茹噎，岂知王豹竟吞声。","若为更得形容尽，曲折浮沈怨慕情。"]},{"t":"戏咏花鸟名 其一","f":"七言律诗","c":["绿窗莺唤起来时，不分香名属玉儿。","长寿楼中曾斗酒，合欢帐里更联诗。","音生晓月鸣批颊，晴浸秋波浴画眉。","蝶粉团香凝白雪，背人含笑拥乌丝。"]},{"t":"戏咏花鸟名 其二","f":"七言律诗","c":["呼卢争戴胜筹时，转觉轻盈属玉儿。","长寿楼空留斗酒，合欢床窄更联诗。","从他有怨教批颊，却自无言也画眉。","蝶粉团香凝白雪，背人含笑饰胭脂。"]},{"t":"春怀","f":"七言律诗","c":["碎擘桃花泛酒卮，对春还咏惜春诗。","莺能承意歌杨柳，蝶解含情舞柘枝。","世事尽他无定论，醉怀却自有开时。","岁寒亭下青松树，春去春来总不知。"]},{"t":"病起书事","f":"七言律诗","c":["性恬乖剌与粗疏，谁说清狂痼疾除。","可要更须教失马，祗应元□示悬车。","胜游索办烟霞屐，绪业非攻种树书。","多幸老民俱有趣，醉乡日月是华胥。"]},{"t":"病中述怀","f":"七言律诗","c":["雨声一夜到床头，一洗胸中万斛愁。","世态低昂付蛮触，宦途消息寄蜉蝣。","暑天卧病犹痴较，少日勤行半素休。","频梦江头岂无意，此身栩栩见沙鸥。"]},{"t":"即事","f":"七言律诗","c":["可人天气不寒温，诗满花笺酒满尊。","乱列晓山烟淡碧，漫流春水雪消浑。","四时风月无佳客，一榻琴书静掩门。","吟罢新诗频酌酒，别离情绪已黄昏。"]},{"t":"马上偶得","f":"七言律诗","c":["十年南北复西东，万里乾坤走断蓬。","燕子不来春淡淡，雁行空过雨濛濛。","故园花柳依然好，瀚海风光却不同。","寂寞清明寒食节，几声啼鸟怨东风。"]},{"t":"石梁","f":"七言律诗","c":["飞梁横绝浪花中，寒压骊龙弟几宫。","却月晖光围倒景，渴虹垂影跨长空。","淩波自接升仙路，炼石应劳并鬼工。","好梦青云上天去，未应人世限西东。"]},{"t":"饮凤凰山醉仙洞有歌稼轩郑国正应来死鼠叶公原不好真龙瑞鹧鸪者因为赋此","f":"七言律诗","c":["凤凰山色媚芳尘，不著诗仙写不真。","灵境爱饶花气味，老怀欣办酒精神。","烟霞里面长春洞，天地中间独醉人。","未续离骚唯痛饮，可凭谁说与灵均。"]},{"t":"阅旧稿有出六盘时干戈旁午惊尘日书剑零丁去国时之句因足成之","f":"七言律诗","c":["点检吟怀课所思，最关情是旧题诗。","干戈旁午惊尘日，书剑零丁去国时。","陈事上心空扰攘，当杯入手莫推辞。","春风信染千红紫，合染幽人两鬓丝。"]},{"t":"桃花源别业重理旧稿戏题","f":"七言律诗","c":["无忧树下无怀氏，独醉园中独醉仙。","八斗待量珠玉价，等閒不若一囊钱。","辞锋几挫毛元锐，心印都传楮守玄。","未碍刘郎长占断，桃花流水洞中天。"]},{"t":"自题拟乐天","f":"七言律诗","c":["有客清谈如妙玄，笑愚声迹不虚传。","风花烟月三千咏，拙直膏肓二十年。","玩世遨头狂醉隐，果真称首浪游仙。","不知乐圣轩窗下，解到南华弟几篇。"]},{"t":"庚申岁夏因六盘之变尝与巴特玛其名者质诸天日约分二道邀击而师颇闻其人为敌谋将遂赋此为食言者之戒","f":"七言律诗","c":["定交情分一何深，许论传烽过烛阴。","约雪神羞同脱口，誓清天步共铭心。","我平高阙旋龙勒，君取花门出凤林。","须是存盟如皦日，岂宜相与世浮沈。"]},{"t":"猎北平射虎","f":"七言律诗","c":["飞控遗风猎北平，澹阴平野草青青。","南山白额威何振，东海黄公厌不行。","径捷鸣髇延满月，奄惊繁弱激流星。","由来一片斓斑锦，别在神机霹雳声。"]},{"t":"阆州海棠溪拟乐天","f":"七言律诗","c":["阆苑仙从阆苑西，纵游还过海棠溪。","径随翠碧穿花去，却听黧黄绕树啼。","回玉花骢锵玉勒，约金丝柳上金堤。","五城胜概歌诗草，醉墨淋漓尽赫蹄。"]},{"t":"临潼九龙玉莲二汤合为道院","f":"七言律诗","c":["九龙汤涌玉莲香，龙去莲枯堕渺茫。","梦雨已迷三里雾，悲风空泛五云浆。","长生殿圮金沙冷，王母祠倾玉蕊荒。","终古曲江江上月，恨和烟草怨霓裳。"]},{"t":"游奉圣州龙岩寺","f":"七言律诗","c":["卧龙高卧几黄昏，依约灵岩隐卧痕。","云磴屈蟠侵鸟道，翠屏环合掩山门。","净名花界开中叶，兴圣莲宫庇上尊。","不就卜居殊胜地，忍冲烟霭下孤村。"]},{"t":"次韵舟行次蓬州游历州境憩蓬莱堂","f":"七言律诗","c":["共传灵境可摅怀，指示龙章与凤台。","白鼻騧腾横吹去，黄头郎递棹歌来。","青山绿水纡回处，万紫千红次弟开。","庵独醉仙无定所，素知元只在蓬莱。"]},{"t":"岳台怀古","f":"七言律诗","c":["万古神州就陆沈，战尘犹自结閒阴。","日边箫鼓衣冠尽，天外楼台草木深。","江月和愁传桂烛，野棠无语寄春心。","如何黄鸟年年在，不说东风怨上林。"]},{"t":"三月到旺结河有感","f":"七言律诗","c":["杨柳盈堤冻未苏，年年旺结旧程途。","经春积雪随山在，慰眼幽花到处无。","帘外月明人影寂，枕边灯暗雁声孤。","又还虚度清明节，独倚东风酒一壶。"]},{"t":"中统庚申诣阙寓居宫东寺口号","f":"七言律诗","c":["日华浮动卧龙邱，便觉妖氛散不收。","佳气郁葱形胜地，霏烟纷郁帝王州。","碧莲花拥三千界，白玉城骈十二楼。","可要翠深环宝势，不容沧海更横流。"]},{"t":"鄂诺道中","f":"七言律诗","c":["岁月峥嵘老思荒，句中无画写荒凉。","山山水水三千里，雨雨风风一万场。","致福不应烦失马，耽书堪笑竟亡羊。","百花留得芳菲在，倾盖丹心捧太阳。"]},{"t":"游大翮山","f":"七言律诗","c":["路盘空翠上青天，下望皇州一点烟。","云叶堆来人脚底，日华垂在马头前。","露花烟草芬兰麝，百籁群鸣播管弦。","可笑旧游王次仲，不来寻谒酒中仙。"]},{"t":"寓历亭","f":"七言律诗","c":["人閒无地避歊蒸，忽觉凉从四座生。","好在医无闾上月，为临华不注边城。","千年辽鹤三生梦，一曲南风万古情。","今日濯缨知有处，大明湖净舜泉清。"]},{"t":"秋日酌兰皋亭","f":"七言律诗","c":["朝来爽气扑兰皋，窃喜西山隶我曹。","孤奋自甘栖澹泊，五噫宁苦遂清高。","逆知江上鲈鱼脍，未抵尊前紫蟹螯。","谁似无何狂醉隐，痛延杯酌咏离骚。"]},{"t":"侯家","f":"七言律诗","c":["探春人喜报来频，春色看看满玉津。","红杏雨疏桃脸嫩，绿杨烟冷黛眉颦。","凤凰箫咽歌声转，鹦鹉杯深酒味醇。","应是双溪新领要，园林良是主人新。"]},{"t":"松声 其一","f":"七言律诗","c":["数閒茅屋起云峰，明月天高睡正浓。","乍觉夜倾千丈雨，不知风度一山松。","人閒拍岸惊秋浪，海底喧天怒老龙。","洗尽生平尘垢虑，浩然爽气溢心胸。"]},{"t":"松声 其二","f":"七言律诗","c":["苍苍郁郁本无情，何处风来吹有声。","四面迅雷平地起，九江湍浪一时倾。","关山夜静蛟龙吼，河汉秋高鸾凤鸣。","风定松閒无个事，喧天动地可来惊。"]},{"t":"松声 其三","f":"七言律诗","c":["幽人耳净听铮铮，一夕西风梦里惊。","非玉非金非草木，似琴似阮似秦筝。","夜间拍枕三更雨，秋冷喧天万灶兵。","孤坐茅檐对明月，一声声是自然声。"]},{"t":"松声 其四","f":"七言律诗","c":["岩声何事韵铮铮，风入寒梢鸟自惊。","七岭夜寒筛汉月，九霄霜冷奏秦筝。","归心唤起陶元亮，醉耳还醒阮步兵。","拟赋新诗慵把笔，划然长啸两三声。"]},{"t":"春梅","f":"七言律诗","c":["一夕雨风粹玉尘，晓来策蹇到江滨。","枝头金蕾安排破，雪里冰姿准备春。","倚竹欲形閒态度，临歧微露旧精神。","此花底事年来早，有意调羹近紫宸。"]},{"t":"梅魂 其一","f":"七言律诗","c":["忆昔西湖雪霁芳，转头潇洒寿阳妆。","角中吹散含新怨，梦里飞来带旧香。","堪恨月楼三弄笛，漫劳诗客九回肠。","徘徊目断江边使，为问春光底处藏。"]},{"t":"梅魂 其二","f":"七言律诗","c":["玉骨消沈一梦长，罗浮山下几昏黄。","祇须怨笛招遗韵，枉托风媒返旧香。","苍海楼台浑缥缈，紫阳宫阙更微茫。","宝猊只篆灰心字，谁并同心与倩娘。"]},{"t":"谨和尊大人领省雷字韵","f":"七言律诗","c":["乾坤昨夜净氛埃，春到南轩一树梅。","驿使浮沈芳信断，东君委曲腊封开。","竹筛凉月窗前雪，风送寒涛枕上雷。","清入梦魂眠不得，划然长啸出门来。"]},{"t":"独醉园梅数年无花今岁特盛中觞有索赋梅词者为赋","f":"七言律诗","c":["世外佳人幼妇辞，爱春移入背阴枝。","鼙婆进奏玉莲锁，云子劝延金屈卮。","世事尽他无究论，醉怀原自有开时。","由来萼绿花心在，拟倩梅仙遣所思。"]},{"t":"和人落梅","f":"七言律诗","c":["晚来江上断人肠，占断严凝忆独芳。","易得飘零惊短笛，不胜憔悴褪残妆。","月明霜重得谁惜，尘暗云埋犹自香。","拟嫁与春春不管，却随流水怨昏黄。"]},{"t":"落梅","f":"七言律诗","c":["咽咽戍楼三弄角，悠悠江使九回肠。","一窗夜月宜怜影，满地春风自好香。","憔悴纵无蜂蝶怨，风流合有燕莺忙。","水边篱下将谁惜，却对幽人怨寿阳。"]},{"t":"拟咏落梅","f":"七言律诗","c":["傲雪欺霜独自芳，雪消寒尽老何妨。","飘零最是堪怜处，桃李无情空妒香。","夜月有知应懊恼，春风何计可商量。","自从一识东君面，赢得林生满径霜。"]},{"t":"玉泉新墨","f":"七言律诗","c":["柏液煤楺冷剂香，枯胶点漆自仙方。","风生白兔瞳睛瑩，电走碧云鸦背光。","可笑千金高索价，更怜百纸碎裁钢。","伫情看了人争道，且置三张在一傍。"]},{"t":"从涣然觅纸","f":"七言律诗","c":["珍重含章承素业，价高摛藻掞皇州。","祇缘布濩三都赋，更欲恢张五凤楼。","元锐铭心由白战，陈京研思为冥搜。","风流坐上芸窗下，落纸云烟待解忧。"]},{"t":"谨次尊大人领省火绒诗韵","f":"七言律诗","c":["雨击风摧岁月空，卧沙老木暗藏绒。","一弯镰撇手中月，几点尘飞吻角风。","放出夜光应有力，挽回春色岂无功。","燧人勋业今安在，惟有真空用不穷。"]},{"t":"为曹南湖引阮摘赋","f":"七言律诗","c":["坐对王郎手语禅，绕盘鸣玉漱流泉。","千年野鹤穿孤月，万壑松风入四弦。","贺老定场将梦断，桐孙倾韵与心传。","仲容原是青云器，不短扬雄草太玄。"]},{"t":"咏阮","f":"七言律诗","c":["点铁成金自有神，夺胎无骨示天真。","惊虬昂首出月魄，老鹤奋身当桂轮。","意足声圆还自问，变风变雅更何人。","应疑太白司花界，长抱琵琶控好春。"]},{"t":"杨妃菊","f":"七言律诗","c":["脉脉无言入醉乡，风流犹记在昭阳。","露晞金掌遗春梦，月挂瑶台怨夜妆。","不忆千年倾国艳，祇消一缕返魂香。","无情莫比吴原草，更忍尊前舞断肠。"]},{"t":"对城南池莲招曹南湖","f":"七言律诗","c":["淩波延伫澹相留，应托微波怨未休。","閒偃露盘如欲语，骤倾风盖却回头。","歌珠串脱横塘雨，醉玉香凝罨画楼。","好在水仙繁会处，烂张云锦待仙舟。"]},{"t":"天香台牡丹","f":"七言律诗","c":["牡丹名品数姚黄，分外精神分外香。","气节得教称贵客，风标元索号花王。","玉妃醉露足春梦，魏后倚风呈晓妆。","天赐宠荣光价在，得无夸丽酒仙乡。"]},{"t":"天香台单叶牡丹率成重叶多叶千叶为赋此纪之","f":"七言律诗","c":["灵根原自养黄芽，标置长春胤此花。","心喜芳时回上叶，眼明今日见重华。","玉楼叠起连珠树，宝阁成层结绮霞。","谁在一天香阵里，得人争指是仙家。"]},{"t":"唐家牡丹","f":"七言律诗","c":["花萼相辉瑞锦屏，探春半度恋春情。","貌同腻玉镂雕就，衣是缕金丝织成。","应笑玉华头髻重，爱更金粟擘环清。","温柔谁更鲁倾国，只数杨家姊妹名。"]},{"t":"荐福山寺殿前牡丹","f":"七言律诗","c":["天女盘中见此花，更须宜在竺仙家。","香名夙著谢灵运，标致竟输杨子华。","斗日烂摛丹地锦，瑞云閒衬赤城霞。","可怜宗正皆芳宴，不著歌诗触处誇。"]},{"t":"饮独醉园牡丹下戏题","f":"七言律诗","c":["谁伴花王同乐国，温柔乡里醉乡侯。","莫推花酒为閒事，难得侯王结胜游。","婪尾岂辞延入手，招腰可是要缠头。","已将八斗新珠玉，买断春风与帝休。"]},{"t":"题西庵所藏佛牙","f":"七言律诗","c":["旃檀奁里贮灵牙，来自中天尊者家。","瑩色冷侵秋夜月，真光明射晚晴霞。","本同舍利原无别，疑是金刚事有差。","犹忆广长舌左右，嚼咀风雨震雷车。"]},{"t":"太极宫","f":"七言律诗","c":["空翠凝香激紫微，步虚声荡綵云帷。","金人承露夜应怪，玉女散花春不知。","别起蟾宫修素月，更明龙烛浴朱曦。","醉来还袖昭华琯，待就仓鸾背上吹。"]},{"t":"戏书太极宫旧碑阴","f":"七言律诗","c":["忆乘辂络命鱼车，登白空山诣紫虚。","天籁虚徐生洞府，风箫冷激在楼居。","九成绛雪无消息，三变玄云孰埽除。","唯记清宁年月日，五云关吏少霞书。"]},{"t":"登玉皇阁周览燕都偶而成书","f":"七言律诗","c":["势倾幽谷控扶桑，琪树霓旌照八荒。","一种世间豪侠窟，九重天上利名场。","翠帘笼日纵金凤，清跸揭云朝玉皇。","何事未祈心事了，更休颓思愧平章。"]},{"t":"游仙","f":"七言律诗","c":["六铢仙帔映花朝，护跸痴龙胆气骄。","五色云车回日驭，九葩芝盖抵星桥。","閒携凤女批明月，还纵鸾歌透紫霄。","半夜水晶宫殿里，碧桃花下更闻箫。"]},{"t":"琳宫月夜宴集","f":"七言律诗","c":["红雪香团露井桃，彩云轻叶拥霓旄。","三千玉女霞妆薄，十二珠楼月烛高。","花界不应辞琬液，海人休便献龙膏。","文章好在通明殿，醉墨淋浪凤锦袍。"]},{"t":"奉答翠华仙伯","f":"七言律诗","c":["龙烛飞光拂羽林，佩环声急荡疏阴。","黄金阁浸明河冷，白玉楼涵碧雾深。","云隔凤箫春澹澹，月依鸾旆夜沈沈。","的知天必从人愿，得得亲来拜好音。"]},{"t":"题长春宫瑞应鹤诗二首 其一","f":"七言律诗","c":["蕊宸华供列仙班，灵境清沈白日閒。","鹤驾竞来趋北极，嵩呼原不离南山。","玉皇宫殿红云里，金母池台碧雾閒。","休应是彰皇化处，镇长春色在人寰。"]},{"t":"题长春宫瑞应鹤诗二首 其二","f":"七言律诗","c":["千年物外还丹使，岂不衔珠首重回。","遽远空香辞阆苑，竞随虚驾到蓬莱。","仙家得表明时兆，寿域原从此日开。","不是瑶台无恋处，九苞金凤感将来。"]},{"t":"赠坐竿道士","f":"七言律诗","c":["说似蓬莱恐更迷，刘郎亲涉武陵溪。","梭抛霞绮龙鳞涩，辂展虹桥凤翅齐。","棋烛纵光然日月，宴衣分色剪云霓。","桃花零落春风起，笑杀王嫱醉似泥。"]},{"t":"寄白云庵赵鍊师","f":"七言律诗","c":["郊园日涉应成趣，远谢嚣氛思不群。","罨画溪边扃岫幌，碧桃花下列仙班。","千年往事随黄鹤，一片閒心伴白云。","纵倚风书徵不起，可无芳信寄王孙。"]},{"t":"留题大防山孔水","f":"七言律诗","c":["尾闾寒泄碧云浆，谁动霓裳混渺茫。","惬意玉龙深酿雨，纵游赪鲤静喷香。","流通瑶水明霞近，洞接桃源白日长。","相得群仙情未切，又抛花片赚刘郎。"]},{"t":"登燕都长松岛故基","f":"七言律诗","c":["缥缈笙歌拂紫霄，水晶宫殿荫兰皋。","势倾沧海风云动，秀出中天气象高。","可是浪悬秦照胆，不知谁玩汉吹毛。","流莺似说伤心事，啼遍宫前小野桃。"]},{"t":"又登琼华岛旧址次吕龙山诗韵","f":"七言律诗","c":["不放笙歌半点閒，紫霞香露怕馀残。","水摇千尺地中月，人倚九重云外栏。","碧落更谁乘彩凤，翠屏空自掩金銮。","蓬莱宫阙遗基在，思对秋风仔细看。"]},{"t":"九龙谷","f":"七言律诗","c":["六龙遗蜕九龙蟠，终古蟠龙气象閒。","逐鹿得非缘石马，啼鹃应自恐桥山。","披天一鼎神移去，落日孤林鸟自还。","犹托哀湍浑自说，悔将春梦到人閒。"]},{"t":"发药儿岭过永定关诗","f":"七言律诗","c":["山灵应也厌嚣埃，宛写幽尘篆绿苔。","望气莫疑非尹喜，附舆须自是韩哀。","侧骈翠壁侵云起，斜抱横流捲地来。","好在旧时堤畔柳，不知青眼盼谁开。"]},{"t":"伤古城次友人韵","f":"七言律诗","c":["每爱登临趁雨晴，凉生襟袂晚风清。","草铺平野重祠绿，水引斜阳一线明。","残柳断碑兴废地，淡烟啼鸟古今情。","繁华消尽市朝变，花落月明空水声。"]},{"t":"和人黄龙冈怀古","f":"七言律诗","c":["黄龙不负覆舟飞，天意人情尽可知。","一掷乾坤将自赌，两周甲子是谁推。","若须要处长生鹿，可是曾收越影骓。","睿德神功无籍在，土花封合御园碑。"]},{"t":"谨和尊大人领省沙场怀古兼四娱斋韵","f":"七言律诗","c":["小沙场没铁衣堆，忆昔英雄一窖灰。","青冢荒凉遗旧怨，黑河呜咽写馀哀。","书痴信手翻新曲，诗瘦扶头怯大杯。","汗漫谪仙游八表，子卿归后几人来。"]},{"t":"读汉书偶成寄李稚川","f":"曲","c":["看尽人閒傀儡棚，不知笑杀老禅僧。","风云依合无多日，禾黍高低没五陵。","纸上功名休理会，梦中身世尽翻腾。","从今?取生平醉，莫惜王公唤不应。"]},{"t":"见曹丕受禅碑有感","f":"七言律诗","c":["从此建安王气衰，君臣离合可伤悲。","几人石上留名日，千载世间不毁时。","过客未知谁氏迹，野夫犹道汉家基。","临风读罢一长叹，却是曹丕受禅碑。"]},{"t":"因读史偶成即书","f":"七言律诗","c":["一曲狂歌万古情，惜难将日系长绳。","未容狐兔游秦苑，已放牛羊入汉陵。","梦稳几曾惊鸟唤，酒酣长欲看云腾。","莫将心事投明月，领取繁花半夜灯。"]},{"t":"题汉武内传","f":"七言律诗","c":["烂烛神光射九霄，空香虚驾绕霓旄。","将临紫极调金液，更入明霞漱玉膏。","瑶水露寒芳草歇，鼎湖烟暖景云高。","可凭谁问秋风客，忍委三山与怒涛。"]},{"t":"宫怨","f":"七言律诗","c":["脉脉慵招凤翼箫，沈思尘事自无聊。","不唯只妒莺声巧，且自尝憎燕语娇。","照胆光芒殊未歇，守宫颜色若为消。","梅花独自惊时节，肯放春风到柳条。"]},{"t":"哀长安","f":"七言律诗","c":["汉家宫阙五云閒，不似当时梦一般。","金殿夜延萤烛暗，翠帘风窣月钩閒。","笙歌竟逐人消息，楼观空馀燕往还。","斜日亭亭淡无语，为谁空下九嵏山。"]},{"t":"炀帝","f":"七言律诗","c":["叠鼓凝笳宴未阑，战尘回首满人閒。","南山翠竹长不起，东海洪波流己乾。","宝驾陆沈池馆尽，锦帆星散水云閒。","空馀仁寿宫前草，遥接雷塘野树烟。"]},{"t":"周室","f":"七言律诗","c":["风满珠帘月殿凉，水纹珍簟浪生香。","翠钗飞燕绕春梦，宝镜舞鸾呈晓妆。","空自不来行暮雨，为谁无语背斜阳。","含情拟绝淩波路，未分莲花是六郎。"]},{"t":"题杨贵妃遗事","f":"七言律诗","c":["玉笛声沈玉漏长，玉环心事夜来香。","如何更入金诃子，却比无言睡海棠。","双凤扶云留翠辇，九龙伏雨去莲汤。","千秋万古嵬坡梦，应绕新台怨寿王。"]},{"t":"汉宫","f":"七言律诗","c":["幻出壶天醉碧桃，旋开云窦挹琼膏。","龙蟠烛影承香辇，凤拥箫声绕赭袍。","织女机临银汉动，捧盘人共玉蟾高。","如何今日猗兰殿，吹尽雄风到野蒿。"]},{"t":"炀帝故宫","f":"七言律诗","c":["凤跸鸣銮入暮云，缭墙倾影障苔痕。","三千歌舞春风起，百二山河野日昏。","石马不嘶春自老，玉楼无迹燕犹存。","旧时长送龙舟水，空伴寒潮过海门。"]},{"t":"绣岭宫","f":"七言律诗","c":["日射天门绮雾开，蕊珠宫阙照蓬莱。","霓裳动入青冥去，羯鼓声含白雨来。","六辔玉虬笼剑佩，九重花界映楼台。","惜无测术天公意，忍竭恩华养祸胎。"]},{"t":"次赵虎岩游香山见故宫诗韵","f":"七言律诗","c":["往事惊心话欲休，并随閒望入层楼。","为龙为虎人谁在，鸥去鸥来心自流。","翠辇影沈天地老，紫箫声断海山秋。","长歌一曲西风起，手把残花尽日留。"]},{"t":"游玉泉","f":"七言律诗","c":["纷披容与纵笙歌，蕙转光风艳绮罗。","露冷桃花春不管，月明芳草夜如何。","灵珠浩荡随兰棹，云锦低回射玉珂。","深入醉乡休秉烛，尽情挥取鲁阳戈。"]},{"t":"次张子敬游玉泉诗韵","f":"七言律诗","c":["并觉氛埃不更侵，水天澄碧自相临。","纵游人在知鱼乐，浪作诗来羡鸟吟。","花阵尽缘芳草合，香云浓锁洞房深。","从今落笔惊风雨，要识春风是此心。"]},{"t":"次赵虎岩过玉泉怀古韵","f":"七言律诗","c":["玉泉潇洒已年深，昔日游踪尚可寻。","有意林泉堪作伴，无情岁月任相侵。","携壶乘兴开怀饮，策杖閒游信口吟。","地僻山空无过客，松杉庭户夜沈沈。"]},{"t":"宫词 其一","f":"七言律诗","c":["玉辇声沈不再过，锦屏寒影梦如何。","露花凝夜香珠冷，苕径封春翠靥多。","怨烛泪乾遗晓月，妖莲心苦起秋波。","姮娥万古青天在，剩比人閒受折磨。"]},{"t":"宫词 其二","f":"七言律诗","c":["蜂粉蜂黄事已休，凝尘空满玉搔头。","海棠酣睡醉无力，人柳痴眠閒自愁。","深掩绿云笼晓月，乱飘红雨涨春流。","不知燕子来时节，几度双飞入画楼。"]},{"t":"战三封","f":"七言律诗","c":["河汉吞声自请平，冷光横绝见长庚。","骤挥戈去日西坠，触折柱来天北倾。","威控望舒延苦战，势微滕六纵疑兵。","若非不是云龙变，一举谁收万古名。"]},{"t":"征不庭","f":"七言律诗","c":["闻说天兵下八埏，自临华夏益精妍。","龙拿虎掷三千国，岳镇渊渟五十年。","应欲昭章新日月，更为弹压旧山川。","可怜棘霸皆儿戏，不似神微计万全。"]},{"t":"侍宴万安园","f":"七言律诗","c":["六龙捧日上层霄，人海妖氛时自消。","五彩凤声喧鸟道，九光芝色焕兰苕。","宴酣兜率黄金鼓，吹裂昆崙紫玉箫。","更觉钧天佳气合，万枝华烛动虹桥。"]},{"t":"小猎诗 其一","f":"七言律诗","c":["翠华东出万安宫，猎猎旌旗蔽碧空。","鹦鹉林停纵金勒，鹔鹴裘袒控雕弓。","塞鸿惊带鹅毛雪，野马尘飞羊角风。","万骑耳边惊霹雳，一声鸣镝暮山红。"]},{"t":"小猎诗 其二","f":"七言律诗","c":["翠华十月猎川中，马上书生自不穷。","济济威仪周制度，番番人物汉英雄。","一封云汉飞金诏，万国君王朝玉宫。","四合相连几千里，熊罴封入我牢笼。"]},{"t":"宽甸有感","f":"七言律诗","c":["黯光宽甸旧烟光，锋镝纵横扰帝乡。","昔是翠华临幸地，今为白草战争场。","阴符消息成金匮，雄战分明胜铁枪。","从此不应将北极，等閒容易许禺强。"]},{"t":"贤王有云南之捷","f":"七言律诗","c":["诏出甘泉总六军，渡泸深入建元勋。","旌旂动地惨遮日，金鼓震天寒搅云。","鉴战折冲貔虎阵，先声靡拉犬羊群。","中朝词客如椽笔，拟与名王纪所闻。"]},{"t":"献上贤王","f":"七言律诗","c":["神烛高明日月齐，司分兰艾入春畦。","虹霓渴饮沧溟竭，星斗光垂碧落低。","寒暑纵催穷塞雁，晨昏宁属禁城鸡。","无能自忖人堪笑，唯有青云是旧梯。"]},{"t":"近闻贤王春水因寄","f":"七言律诗","c":["风揭鸳鹅扰绿漪，鸣蝉声促越重围。","海东青帖翠云起，照夜白侵瑶水飞。","玉鹭乱飞梨雪去，彩鸳争绝浪花归。","非熊未必当时纪，依旧烟波绕钓矶。"]},{"t":"大江篇寄上贤王以代谢章兼贺平云南之捷","f":"七言律诗","c":["冷浸乾坤影荡摇，狂澜万古自滔滔。","游风欲动雪还沸，淫雨不收天更高。","留取蛇珠弄明月，乞持虹钓拂神鳌。","渥洼已厌江南草，何事灵胥有怒涛。"]},{"t":"挽皇太子词","f":"七言律诗","c":["象辂长归不再朝，痛心监抚事徒劳。","一生盛德乾坤重，万古英名日月高。","兰殿好风虽领略，桂宫愁雨自萧骚。","如何龙武楼中月，空照丹霞旧佩刀。"]},{"t":"韩省干子平荐章应格朋友漠然未知忽改京秩作七言近体一首贺之","f":"七言律诗","c":["山雌泽啄竞腾轩，孰与昂驹局短辕。","造物至公殊勿置，穷交未喻柱焦煎。","凤批一诺膺天陟，马颈三鞶朝日边。","虎鼠狞尪随秉笔，铨曹常格勿从旃。"]},{"t":"高城曲","f":"五言绝句","c":["城高一百尺，枉教人费力。","贼不从外来，当察城中贼。"]},{"t":"金微道","f":"五言绝句","c":["茫茫苜蓿花，落满金微道。","一千里骥足，十二閒中老。"]},{"t":"小猎诗","f":"五言绝句","c":["虎落入长围，期门突似飞。","乌号惊霹雳，白额藉忘归。"]},{"t":"留别赵虎岩吕龙山","f":"五言绝句","c":["燕南春色老，燕北草初肥。","露冷野花瘦，月明江树稀。"]},{"t":"怀赵虎岩吕龙山","f":"五言绝句","c":["六年风雨夜，一寸别离心。","日莫步芳草，相思尘满琴。"]},{"t":"怀舜钦","f":"五言绝句","c":["过雁三四声，相思千万里。","策杖倚西风，行云渡秋水。"]},{"t":"寄杨诚之","f":"五言绝句","c":["相去一万里，相思堪倚楼。","汉宫临薄莫，羌笛怨高秋。"]},{"t":"寄李东轩","f":"五言绝句","c":["一纪不出门，三年不窥园。","有谁曾得似，高士李东轩。"]},{"t":"送赵伯玉行","f":"五言绝句","c":["去雁失归群，孤声不可闻。","一楼花外月，千里陇头云。"]},{"t":"怀高敞","f":"五言绝句","c":["春满凤城陌，惜春人未来。","相思不可寄，何处有高台。"]},{"t":"代寄","f":"五言绝句","c":["露委花团雪，夜寒香著枝。","春风殢杨柳，祇是漫摇枝。"]},{"t":"代人寄远","f":"五言绝句","c":["怨蝶休春梦，惊乌绕夜啼。","唯应故山月，相与过辽西。"]},{"t":"拟孟郊古怨","f":"五言绝句","c":["意妾似花枝，愿与春长在。","郎意似花阴，逐日阴移改。"]},{"t":"闺怨","f":"五言绝句","c":["惜春惊白日，不到回心院。","合照妾情人，也逐花阴转。"]},{"t":"池亭睡起","f":"五言绝句","c":["丝雨笼深院，团花皱碧罗。","不怜孤枕梦，终日恋池荷。"]},{"t":"长春阁","f":"五言绝句","c":["院僻人行少，垂杨覆地丝。","阁高秋色早，山远夕阳迟。"]},{"t":"登广寒殿故址","f":"五言绝句","c":["万古消沈尽，浮云事几场。","酣歌颓醉玉，休得问兴亡。"]},{"t":"春晚","f":"五言绝句","c":["雨馀芳草绿，石尽野塘浑。","落日一声笛，断肠人倚门。"]},{"t":"落花","f":"五言绝句","c":["不堪三月尾，风雨又相和。","片片树头少，纷纷地上多。"]},{"t":"独醉园寓兴","f":"五言绝句","c":["百品消愁药，三生解语花。","一时都聚在，方外酒仙家。"]},{"t":"饮逸园","f":"五言绝句","c":["无何有醉隐，称是饮中仙。","玉瀣涵金液，金波养玉泉。"]},{"t":"饮南园","f":"五言绝句","c":["攲红醉浓露，凝碧压芳烟。","我有一壶酒，置君花树间。"]},{"t":"玉窗歌","f":"五言绝句","c":["玉钩垂翠箔，珠幌背兰膏。","花瘦露如洗，月明秋更高。"]},{"t":"夜坐","f":"五言绝句","c":["香起深斋静，横琴夜更幽。","千岩风雨冷，一夜鬼神愁。"]},{"t":"嘲渔父","f":"五言绝句","c":["若为逃世网，却订钓名钩。","自是惊飞尽，群群海上鸥。"]},{"t":"渔父答","f":"五言绝句","c":["世路披天险，名声足是非。","月明风下露，吹笛放船归。"]},{"t":"杂咏","f":"五言绝句","c":["我虽不解事，知时莫如我。","须为扇仁风，吹灭权门火。"]},{"t":"示子","f":"五言绝句","c":["人皆缘禄福，我独以官贫。","富贵莫图著，恐他来逼人。"]},{"t":"荡子","f":"五言绝句","c":["行云思故山，游子何时还。","天地如逆旅，光阴不可攀。"]},{"t":"题西山早梅扇头","f":"五言绝句","c":["西山先得日，南枝先得春。","朱曦与青帝，岂属种花人。"]},{"t":"十六对月","f":"五言绝句","c":["月姊应吞怨，无人写所思。","柔情将绰态，须是破瓜时。"]},{"t":"乐圣斋对酒吟","f":"五言绝句","c":["锦帏五十里，胡椒八百斛。","那能知如许，且尽杯中物。"]},{"t":"春雷琴","f":"五言绝句","c":["素匣开寒玉，乌龙出秋水。","长到夜深时，恐乘雷雾起。"]},{"t":"灯蛾叹","f":"五言绝句","c":["白日不飞出，夜灯安可亲。","比朋不可投，何似暗藏身。"]},{"t":"即事","f":"五言绝句","c":["青州少从事，平田少督邮。","洞庭春色里，谁是醉乡侯。"]},{"t":"钱币","f":"五言绝句","c":["白鹿殊持重，青蚨岂致贫。","不唯堪使鬼，且是更通神。"]},{"t":"得雪斋所遗竹箭因以此寄时雪斋南游未回","f":"五言绝句","c":["适足堪申意，浮游亦识机。","未应为信往，著处即忘归。"]},{"t":"南征过蜀寄题故园","f":"五言绝句","c":["水击三千里，鹏抟九万程。","不应栖隐地，犹待卧龙耕。"]},{"t":"大河篇","f":"五言绝句","c":["怒浪淘晴雪，惊雷日夜奔。","洪流将碧落，空自势相吞。"]},{"t":"次韵阆州述事","f":"五言绝句","c":["首肯唐庚赋，心推郭逸诗。","为谁携斗酒，还酹鲁公祠。"]},{"t":"闺思 其一","f":"五言绝句","c":["雁阵惊秋信，蛩吟袭夜帏。","河源应冻彻，方忆捣征衣。"]},{"t":"闺思 其二","f":"五言绝句","c":["心事苧衣宽，尘锁菱花暗。","春入水声滑，水涵春景淡。"]},{"t":"闺思 其三","f":"五言绝句","c":["问鸿鸿已归，问花花不知。","却把凤凰箫，水晶帘下吹。"]},{"t":"雪岭","f":"七言绝句","c":["折扬霆电决雌雄，霆激狂峰电埽空。","如席片飞何处雪，扑林声振海天风。"]},{"t":"阳关","f":"七言绝句","c":["振威驰突过天山，擒敌如神指顾间。","底事战尘收不起，陈云西下望阳关。"]},{"t":"阴河","f":"七言绝句","c":["虎臣信任国心膂，虓将乐为王爪牙。","贾勇阴河西去路，空拳转斗战龙沙。"]},{"t":"回飞狐","f":"七言绝句","c":["震叠威声径出师，偃旗卧鼓岂无时。","折冲樽俎风流在，未要喧传塞上辞。"]},{"t":"南征纪事","f":"七言绝句","c":["揭雷夔鼓倾天险，络汉虹桥并鬼工。","说是楼船横海将，拟输吴越寿重瞳。"]},{"t":"达兰河","f":"七言绝句","c":["陈云压地势填空，鹅鹳飞驰欲得风。","龙战未分天欲莫，不知谁复是虞公。"]},{"t":"拒马河","f":"七言绝句","c":["陈云北压飞狐口，戎幕西临拒马河。","不独拟虞公止日，誓心期奋鲁阳戈。"]},{"t":"千泉","f":"七言绝句","c":["拥花羽骑附飞翼，倾地铁林和鸟翔。","黄金练愈凝霜重，青玉龙争掣电光。"]},{"t":"西北","f":"七言绝句","c":["不宜有怒徒倾地，自代无功可补天。","争忍竞驱千万骑，又相驰突二三年。"]},{"t":"战沙陀","f":"七言绝句","c":["笑睡龙当独眼龙，更堪都似李横冲。","彼须要不从风靡，除铁山来行战锋。"]},{"t":"玉门关","f":"七言绝句","c":["六合同风奉一君，谁期贵介竟孤恩。","自从五夜传金柝，已早三年闭玉门。"]},{"t":"前出塞 其一","f":"七言绝句","c":["拟取安西袭玉关，短兵鏖战下皋兰。","阴风势挟天山雪，冻彻河源彻底乾。"]},{"t":"前出塞 其二","f":"七言绝句","c":["十年老将浮苴井，万里疲兵碎叶川。","传督诸君传诏令，问何时到海西边。"]},{"t":"后出塞 其一","f":"七言绝句","c":["并吞处月下楼阑，克复金微静铁关。","准拟凿空通四海，会须鞭石到三山。"]},{"t":"后出塞 其二","f":"七言绝句","c":["誓洗兵氛雪国雠，气横辽碣紫山秋。","岂容日下西王母，只属东西海尽头。"]},{"t":"丁灵二首 其一","f":"七言绝句","c":["长驱席卷尽连营，震詟禺强撼北冥。","虎豹骑从云骑队，又随横野过丁灵。"]},{"t":"丁灵二首 其二","f":"七言绝句","c":["月朘日蹙漫逃天，迫胁丁令地一边。","怅不似从东海畔，联珠营直到虞渊。"]},{"t":"秋山二首 其一","f":"七言绝句","c":["万骑龙趋两队分，翠华方自发期门。","内官急把朱旗飐，传道先教诏虎贲。"]},{"t":"秋山二首 其二","f":"七言绝句","c":["两龙如雾发璿台，蔽日旌旗四面开。","疑自锦林花嶂里，建章营骑下天来。"]},{"t":"庭州","f":"七言绝句","c":["星罗游骑遍氛埃，似与颓风下九陔。","可道汉家哀痛诏，未应元自为轮台。"]},{"t":"济黄河 其一","f":"七言绝句","c":["雪滚洪流激怒涛，何时清澈见秋毫。","冰夷应讶无持赠，莫认精诚是寸胶。"]},{"t":"济黄河 其二","f":"七言绝句","c":["回驰声势出昆崙，拒尽人閒要路津。","快著灵涛天上去，就倾银汉洗兵尘。"]},{"t":"金莲花甸","f":"七言绝句","c":["金莲花甸涌金河，流绕金沙漾锦波。","何意盛时游宴地，抗戈来俯视龙涡。"]},{"t":"阿延川诗","f":"七言绝句","c":["倦比纷华说目人，土阶犹恐是劳民。","数间带叶松棚下，指绿莎为翡翠茵。"]},{"t":"过长城","f":"七言绝句","c":["为谁到古长城外，又自经今战地边。","木烛岭空悬素月，炉门山只锁荒烟。"]},{"t":"沙渍道中","f":"七言绝句","c":["去年寒食在天涯，寒食今年又别家。","天北天南人万里，春风开尽马莲花。"]},{"t":"过骆驼山 其一","f":"七言绝句","c":["天作奇峰象橐驼，人閒牧圉肯来过。","祇缘顽犷成无用，不识疮肩陟峻坡。"]},{"t":"过骆驼山 其二","f":"七言绝句","c":["昔驾朱轮白橐驼，石驼曾见屡经过。","苍颜今日应难识，瘦马服箱转旧坡。"]},{"t":"金满城 其一","f":"七言绝句","c":["金满名城果是谁，分明须只是痴儿。","想来可是教人笑，金满城时是几时。"]},{"t":"金满城 其二","f":"七言绝句","c":["便得城中垛满金，不应将买住光阴。","愈奇梦渴何生赋，足见从来不足心。"]},{"t":"渡陷河","f":"七言绝句","c":["天幕旁围翡翠茵，自来元是自迷津。","谁期也值南风起，吹得黄沙不见人。"]},{"t":"翌日渡东陷河","f":"七言绝句","c":["水碧天临碧玉津，上无纤翳下无尘。","畏途也幸逢今日，特地清明不陷人。"]},{"t":"过无定河 其一","f":"七言绝句","c":["一自扬鞭过上州，若为痴绝漫迟留。","为怜此水浑无定，引得龙泉也乱流。"]},{"t":"过无定河 其二","f":"七言绝句","c":["何许颓波是上流，若为洄泬几时休。","如今浅涸仍依旧，漫漶东西到处流。"]},{"t":"过无定河 其三","f":"七言绝句","c":["几临沙步驻骊虬，甚欲源穷问水流。","有底奔波无定在，忽东流了便西流。"]},{"t":"夏州塞外道","f":"七言绝句","c":["如何不渡诺真河，步拙由来步越多。","不是贺人情意好，要临安乐驻行窝。"]},{"t":"入蜀口号","f":"七言绝句","c":["金马可堪充铁马，铁牛那是粪金牛。","虚名岂得为时用，足致天兵下益州。"]},{"t":"游果州凤山观","f":"七言绝句","c":["谁是浮游独醉仙，凤来还上凤山巅。","定应人不知名字，只问南充谢自然。"]},{"t":"过花楼","f":"七言绝句","c":["绝磴层峦路屈盘，欲教人历画图閒。","行云逼渡楼前水，放出林梢一半山。"]},{"t":"晓发牛山驿","f":"七言绝句","c":["山灵护野烟霞静，风伯清尘草树香。","鹤背酒仙和醉梦，不知延入五云乡。"]},{"t":"夜泊青海","f":"七言绝句","c":["归心日夜忆咸阳，海角天涯不是长。","今夜月明何处好，北风低草见牛羊。"]},{"t":"灵州客舍春日寓怀","f":"七言绝句","c":["凉叶常先白露零，草逢寒节未敷荣。","十分体得春消息，不似西风有信诚。"]},{"t":"又和林春日书事","f":"七言绝句","c":["冻折池塘百草芽，断鸿低雪怨凝笳。","晴窗一曲春风咏，开彻满山桃杏花。"]},{"t":"又春日即事","f":"七言绝句","c":["客中草草过清明，寒袭罗衣雨又晴。","梦觉画楼春寂寂，海棠枝上有啼莺。"]},{"t":"野宿 其一","f":"七言绝句","c":["清笳声咽思裴回，漠漠凝云冻不开。","寒入貂裘眠不得，通薪馀火拨成灰。"]},{"t":"野宿 其二","f":"七言绝句","c":["北风作恶晚犹寒，征雁一声云汉閒。","归梦暗随天际月，清辉皎洁满关山。"]},{"t":"马上偶得","f":"七言绝句","c":["谁念天涯久倦游，可堪回首又惊秋。","登高极目莫云碧，衰草荒山不尽头。"]},{"t":"客中吟 其一","f":"七言绝句","c":["旅怀夜永梦偏饶，明灭残灯独自挑。","云外五更征雁尽，帐寒风冷雨潇潇。"]},{"t":"客中吟 其二","f":"七言绝句","c":["白雁飞晴秋夜长，玉兰黄菊傲寒霜。","寸心万里云山梦，一日三秋铁石肠。"]},{"t":"客中吟 其三","f":"七言绝句","c":["万里故人寒旧盟，一尊薄酒正含情。","梦回星斗阑干夜，肠断西风征雁声。"]},{"t":"客中次人韵","f":"七言绝句","c":["塞鸿飞尽野云收，羌笛悠悠漳水秋。","有客北来归未得，倚门长啸看吴钩。"]},{"t":"客中次郭器之诗韵","f":"七言绝句","c":["典尽征衣出醉乡，一回头处九回肠。","黄花满地秋风老，坐数飞鸿到夕阳。"]},{"t":"客中二首 其一","f":"七言绝句","c":["几度求归不放休，翩翩蝴蝶思悠悠。","梦回三径黄花老，题遍一林红叶秋。"]},{"t":"客中二首 其二","f":"七言绝句","c":["咽咽霜笳吹底怨，泠泠山溜泻何愁。","和林望断白云莫，愁入水云东尽头。"]},{"t":"苍官台","f":"七言绝句","c":["层台重到记登临，物态熙熙春意深。","手抚长松望西北，晚云千顷似归心。"]},{"t":"山台","f":"七言绝句","c":["诘曲千层近碧霄，苍松无数绕山腰。","何当一值炎天候，卧听风涛吼夜潮。"]},{"t":"铜雀台","f":"七言绝句","c":["铜雀台荒野草花，阿瞒无复示雄誇。","愁烟忍锁西陵地，向日须曾属汉家。"]},{"t":"癸卯春莫经驻跸院废殿","f":"七言绝句","c":["野粉不留天日表，梦回龙去鼎湖空。","东君若是繁华主，满院落英何处风。"]},{"t":"经丽珍园卫绍王兰香殿故基","f":"七言绝句","c":["国橐危时足藉辞，国香消歇自当时。","教人普结司花恨，恨不留心植佞枝。"]},{"t":"游玉泉山废宫故基口号","f":"七言绝句","c":["殿阁人稀树草荒，旧游空记五云乡。","劫前天地兴亡梦，借问山灵是几场。"]},{"t":"春日游玉泉道院","f":"七言绝句","c":["露桃香汎冷胭脂，低映相思玉树枝。","看取广寒宫殿去，涌金香汎月来时。"]},{"t":"莫春过故宫","f":"七言绝句","c":["柳陌风来雪满沙，锦宫春老野人家。","莺莺燕燕空饶舌，明日西园自落花。"]},{"t":"过庖丁故居","f":"七言绝句","c":["青山坐对幽人老，依旧春风绿庭草。","骑鲸一去不再来，愁看落花曾未埽。"]},{"t":"过万松老人故居有感","f":"七言绝句","c":["忆埽香云谒上方，一天花雨扑禅床。","云归雨敛香花冷，窣堵波沈替戾冈。"]},{"t":"过刘氏园","f":"七言绝句","c":["黄鸟含啼怨未休，露桃倾泪洗凝愁。","多情好在今成燕，双宿双飞直到头。"]},{"t":"莫春过刘氏亭","f":"七言绝句","c":["垂垂帘箔映重门，不避贪飞燕子嗔。","桃李晚来无藉在，乱随风雨并残春。"]},{"t":"太极宫","f":"七言绝句","c":["步虚声入海山寒，并觉空香绕露盘。","天浸月波秋似水，翠鸾飞满玉华坛。"]},{"t":"太和宫","f":"七言绝句","c":["故人心事鬓成丝，犹指颓垣语所思。","元自道陵全盛日，见游麋鹿已多时。"]},{"t":"过大明宫","f":"七言绝句","c":["草展荒凉辇路开，牡丹花谢已葑苔。","苔钱不买春光住，枉了衔花鹿又来。"]},{"t":"琼华岛","f":"七言绝句","c":["万岁山头万树松，万年基业一朝空。","如何太液池中水，依旧罗纹起细风。"]},{"t":"重题燕都玄都观壁","f":"七言绝句","c":["兔葵燕麦尽风埃，何事消沈不再开。","忆得桃花凝笑处，怨春愁篆满苍苔。"]},{"t":"重题隗台玄都观壁","f":"七言绝句","c":["洞锁荒烟藉绿苔，桃花红尽更难开。","刘郎依旧春风里，又到玄都观里来。"]},{"t":"游龙岩寺 其一","f":"七言绝句","c":["上方钟磬隔花闻，便觉仙凡势自分。","争信草灵堂也笑，笑他猿鹤恋松云。"]},{"t":"游龙岩寺 其二","f":"七言绝句","c":["错落岩花是醉茵，景因人胜画难真。","林泉盛迹幽栖地，谁分松云不恋人。"]},{"t":"尝游北禅院鼓子花特盛邻观且有琵琶音后游其所赋此","f":"七言绝句","c":["鼓子花迷香世界，鼙婆声振玉楼台。","郁轮袍竟销沈了，优钵昙空取次开。"]},{"t":"过怀来香山院","f":"七言绝句","c":["院染晴岚树染烟，锦屏花障抱斜川。","不知日莫前途远，为爱青山忘著鞭。"]},{"t":"登吹台凝翠亭偶成","f":"七言绝句","c":["春逐花枝落酒杯，草随春色上高台。","殷勤更把重帘捲，放入青天白日来。"]},{"t":"天津早春","f":"七言绝句","c":["玉京桃李待花仙，培养根芽又一年。","春事动人应不浅，绿莎侵到水傍边。"]},{"t":"早春宴上次高丽国使人诗韵","f":"七言绝句","c":["白玉堂前一树梅，为谁零落为谁开。","人生颜色不常好，且尽生前有限杯。"]},{"t":"玉津池早春","f":"七言绝句","c":["嫩漪縠皱浴鸳鸯，信逐轻鸥下野塘。","红入小桃花绽处，绿莎针短柳丝长。"]},{"t":"白莲池","f":"七言绝句","c":["翠扇平遮罨画楼，玉兰倾露避兰舟。","何如解语花长在，花界长生殿里头。"]},{"t":"无尘亭","f":"七言绝句","c":["白莲自处无尘境，不惜香风隔岸闻。","绝是冰纹珍簟下，水仙潜著水沈薰。"]},{"t":"题霏香亭","f":"七言绝句","c":["为延花事带香霏，弥月兼旬醉不归。","休道未知今日是，当知四十九年非。"]},{"t":"玉津头","f":"七言绝句","c":["桃李无言各自春，韶光堆叠与精神。","半攲倒景薰沈水，径引春风入玉津。"]},{"t":"书斋展西墙","f":"七言绝句","c":["流水平桥花满阑，此欢童辈未期欢。","为嫌不得西山色，乞展西墙两步宽。"]},{"t":"魏焦孝然目其草庐曰蜗牛庐愚以行帐为行窝寻亦号为蜗牛舍云 其一","f":"七言绝句","c":["宴处行窝缩似蜗，推移蜗角叩南华。","调停蛮触将蝴蝶，尽与华胥做一家。"]},{"t":"魏焦孝然目其草庐曰蜗牛庐愚以行帐为行窝寻亦号为蜗牛舍云 其二","f":"七言绝句","c":["绝辔元期绝战尘，指南犹示指迷津。","未应蛮触相倾地，不属华胥枕上人。"]},{"t":"家园即事","f":"七言绝句","c":["莺声圆滑绿阴凉，如是青春白日长。","可笑画梁梁上燕，一年年似一年忙。"]},{"t":"蘅薄","f":"七言绝句","c":["莫惊蘅薄是流芳，芬郁痴仙起草堂。","试听司园须也道，主家门户自来香。"]},{"t":"题梦斋 其一","f":"七言绝句","c":["文府中书五色衣，含章未吐凤先飞。","可堪历历将今是，又对春风较昨非。"]},{"t":"题梦斋 其二","f":"七言绝句","c":["得鹿欢呼事已非，可能蕉覆却空归。","多情最是閒窗蝶，长绕琼华蕊上飞。"]},{"t":"题庸斋","f":"七言绝句","c":["中庸今古几人通，这个机关自不同。","笑杀西天青眼汉，强分南北与西东。"]},{"t":"綵霞亭睡起纪梦书画梦斋壁","f":"楚辞体","c":["浴兰汤兮沐芳华，睡起鸡声透綵霞。","怪得春风教梦稳，尽吹蝴蝶上梨花。"]},{"t":"梦回","f":"七言绝句","c":["恨别故人千里外，梦回孤枕四更过。","轩窗何处无疏雨，不似芭蕉叶上多。"]},{"t":"辛巳年二月初四日夜半后梦中作","f":"七言绝句","c":["春寒每恨花开早，春暖何妨花较迟。","休为玉人惊老去，春寒春暖总相宜。"]},{"t":"纪归梦 其一","f":"七言绝句","c":["睡鸭残香隔梦闻，晓莺啼破五更春。","千秋万古兰窗蝶，只属行云行雨人。"]},{"t":"纪归梦 其二","f":"七言绝句","c":["为蝶为周尽自分，华胥元自是青春。","寒梅计岂罗浮月，偏照淩波解佩人。"]},{"t":"西园春事","f":"七言绝句","c":["西园春事画图中，难状司春造化功。","何限花心争动处，不应都是夜来风。"]},{"t":"西园席上调元子不至","f":"七言绝句","c":["白玉堂前白日长，满前莺燕语如簧。","那知沈饭非荒宴，待与扬鞭问葛彊。"]},{"t":"席上 其一","f":"七言绝句","c":["习饮醉乡抛浩劫，葆真灵液反天和。","方知世上閒滋味，元比神仙不较多。"]},{"t":"席上 其二","f":"七言绝句","c":["彩云行雨阳台梦，罗袜生尘洛浦秋。","飞起一双花上蝶，晚风吹上玉搔头。"]},{"t":"初上缙云五湖别业","f":"七言绝句","c":["旋移松竹养烟霞，人笑猖披不润家。","可要广栽桃李树，年来强半是狂花。"]},{"t":"游壶春园","f":"七言绝句","c":["雨横风狂过一春，养花天气少温存。","满前何限关心事，且是无人详细论。"]},{"t":"翠水别业即事","f":"七言绝句","c":["或命巾车与鹿车，就花深处便倾壶。","风流哲匠天然句，状出双溪醉隐图。"]},{"t":"题易安堂壁","f":"七言绝句","c":["且言居易有何难，俟命由来足易安。","高谢畏途诚可意，见人行险我心寒。"]},{"t":"终夕风雨早起书待旦斋壁","f":"七言绝句","c":["银箭知传弟几更，玉壶清漏不闻声。","雄鸡本是司晨物，未可非时妄一鸣。"]},{"t":"仁寿镇柳浪","f":"七言绝句","c":["柳浪风寒䆉稏香，旋移床就树阴凉。","待教野老题名号，独醉痴仙避暑庄。"]},{"t":"汎城南莲湖","f":"七言绝句","c":["管弦声破水云幽，浪里香风过画楼。","相与兼花折荷叶，乱遮斜日上兰舟。"]},{"t":"题合欢亭","f":"七言绝句","c":["只合欢游引玉舟，骈罗蠲忿列忘忧。","自从收得河边水，须信人閒有帝休。"]},{"t":"曲水游 其一","f":"七言绝句","c":["宴随步障水西东，曲水烟光锦绣中。","杨柳结弮垂柳带，桃花嘶立落花风。"]},{"t":"曲水游 其二","f":"七言绝句","c":["延引仙人莲叶舟，衣冠杂沓载经州。","风流今日兰亭会，引入桃源水上头。"]},{"t":"方湖钓鱼台","f":"七言绝句","c":["杜梨花外杜鹃啼，醉倚春风上钓矶。","真是一声声更切，不知犹更劝谁归。"]},{"t":"玉溪","f":"七言绝句","c":["玉溪声泻玉声寒，流绕祥云瑞霭閒。","却是冰壶凉世界，始知元自在人寰。"]},{"t":"水平桥","f":"七言绝句","c":["洞箫吹罢思无聊，却下閒庭弄柳条。","寂寂小园春昼永，一声啼鸟水平桥。"]},{"t":"白石山","f":"七言绝句","c":["山本无情不解愁，年来底事也惊秋。","古今阅尽兴亡恨，知为何人雪满头。"]},{"t":"山市吟","f":"七言绝句","c":["山阁连城日日新，千形万状只无人。","自分长乐楼台象，不染长安市井尘。"]},{"t":"桃源 其一","f":"七言绝句","c":["洞仙情分与桃源，尽与刘郎旧有缘。","两手未为无用处，不妨和月弄清泉。"]},{"t":"桃源 其二","f":"七言绝句","c":["惊风成陈花委尘，白日如驰催老人。","只须深入桃源洞，留住朱颜占住春。"]},{"t":"过北村","f":"七言绝句","c":["麦穗经场谷尚青，县官严令督秋徵。","嗔他问著西成事，斜倚锄耰并不应。"]},{"t":"观田","f":"七言绝句","c":["漠漠屯云翠拍天，人谣鬼咏是丰年。","老农愁倚锄竿立，五谷虽成不值钱。"]},{"t":"秋日田行","f":"七言绝句","c":["野老郊迎顶斗炉，马前行语更相呼。","田荒室露浑馀事，乞免官徵一岁租。"]},{"t":"灵城元日 其一","f":"七言绝句","c":["惆怅重明竟未回，尘扬沧海劫前灰。","谁期六合披攘际，得引屠苏是后杯。"]},{"t":"灵城元日 其二","f":"七言绝句","c":["未待金鸣送曙光，雁行罗列进桃汤。","如何白兽尊中酒，尽日无人引一觞。"]},{"t":"立春前一日对雪","f":"七言绝句","c":["桃李无言盼断春，值春潜处暖生云。","晚来纵有残风雪，明日人閒总属春。"]},{"t":"立春口号","f":"七言绝句","c":["细风吹绿水生波，翠陌瑶阡艳绮罗。","春信朝来到人世，满城箫鼓醉人多。"]},{"t":"春意","f":"七言绝句","c":["千里万里游子去，一行两行归雁来。","休倚高楼起惆怅，满城桃李为春开。"]},{"t":"春晓 其一","f":"七言绝句","c":["晓来云捲四山晴，睡起池塘春水平。","满眼东风吹柳絮，落花无语怨啼莺。"]},{"t":"春晓 其二","f":"七言绝句","c":["琼枝委露凝香雪，澹月笼花浸麝尘。","唤起丁宁休唤起，苧萝山下浣纱人。"]},{"t":"雷发声","f":"七言绝句","c":["连日阴云惨不开，依稀寒色满楼台。","一台涌地蛰龙起，六合洗天霖雨来。"]},{"t":"寒食日见花开","f":"七言绝句","c":["寒食常年柳未黄，今年花满旧池塘。","如何春色今年早，试对春风笑一场。"]},{"t":"白日","f":"七言绝句","c":["玉涧鸣泉弹洛浦，苍龙横沼写离骚。","晴窗睡起炉烟冷，满院春风白日高。"]},{"t":"临春台","f":"七言绝句","c":["为临春色上歌台，独捲红罗坐绿苔。","忽啭一声穿九陌，永新传送莫莺来。"]},{"t":"七夕 其一","f":"七言绝句","c":["一别相逢泪如雨，不禁憔悴语相思。","佳期咫尺还知不，明日伤情两别离。"]},{"t":"七夕 其二","f":"七言绝句","c":["今日相逢明日离，逡巡离合几多时。","无情云雨休遮隔，人道相逢一岁期。"]},{"t":"七夕 其三","f":"七言绝句","c":["雨洗秋容秋气清，翠帘高捲莫楼晴。","似含羞色谁家女，旋索金针拜月明。"]},{"t":"中秋不见月","f":"七言绝句","c":["夜阑人静漏迢迢，云景无情闭碧霄。","不见嫦娥真面目，裴回虚度可怜宵。"]},{"t":"秋日宜都道中","f":"七言绝句","c":["采莲歌断木兰舟，万里长风入戍楼。","灵凤不来青鸟去，陇头江月可怜秋。"]},{"t":"傩毕酌吟醉斋","f":"七言绝句","c":["毕方鬼蜮避时傩，便觉祈禠气象和。","欢伯解言应也道，最难除得是诗魔。"]},{"t":"咏雪","f":"七言绝句","c":["碧玉壶天白玉尘，十分添起月精神。","从今休作轻盈态，学杀杨花不是春。"]},{"t":"故宫对雪三首 其一","f":"七言绝句","c":["琼室乱穿樵子径，瑶台空映野人家。","天公也是灰心地，更忍教开玉树花。"]},{"t":"故宫对雪三首 其二","f":"七言绝句","c":["更怜琼室伤殷鉴，可是瑶台属夏家。","元自飞花将蒂叶，已抟羊角到中华。"]},{"t":"故宫对雪三首 其三","f":"七言绝句","c":["飘飘举似霓裳舞，烂漫横陈玉树花。","宁知点点飞来意，生自幽人两鬓华。"]},{"t":"园中对雪","f":"七言绝句","c":["惊风不展瑶花限，浩荡年光落又开。","却是仙娥相见处，烂银宫阙玉楼台。"]},{"t":"月台雪霁","f":"七言绝句","c":["水晶帘下玉尘埃，旋逐风姨去又来。","应审素娥殊有待，已悬飞镜上瑶台。"]},{"t":"雪中戏示汉臣","f":"七言绝句","c":["散花台上千山雪，晴雪楼前万树花。","触处造门湛腊酒，更休得问是谁家。"]},{"t":"雪后吟","f":"七言绝句","c":["雪助夜寒更漏涩，何能盼得到天明。","乾坤己落羲和手，休更琼瑶陌上行。"]},{"t":"姮娥","f":"七言绝句","c":["月姊应劳驾望舒，可能圆缺为阳乌。","如何窃尽长生药，却种相思树一株。"]},{"t":"十六夜月得人字 其一","f":"七言绝句","c":["姮娥减却旧精神，桂魄难同昨夜新。","多谢清光不相负，裴回终夕伴诗人。"]},{"t":"十六夜月得人字 其二","f":"七言绝句","c":["底事姮娥出海迟，玉容寂寞不胜悲。","清光未必天边减，冷暖人情亦可知。"]},{"t":"十六夜月得人字 其三","f":"七言绝句","c":["昨夜衔杯写我欢，玻璃万顷桂花寒。","素娥今夕如羞涩，似怨诗人取次看。"]},{"t":"对月吟","f":"七言绝句","c":["谁遣姮娥到画筵，裴回清景不胜怜。","广寒宫殿应萧索，想见人归难自眠。"]},{"t":"炭山窖子店大风后有回风数月不已","f":"曲","c":["西风崛?过柴扉，回裂云衣缠酒旗。","懒举扇来时自蔽，祇知尘污庾元规。"]},{"t":"和林雨大雹有如鸡卵者","f":"七言绝句","c":["谁拥珠玑积玉京，纵期明月易愁晴。","若教不值骊龙睡，不信波斯擅得名。"]},{"t":"雷雹","f":"七言绝句","c":["唤起阿香云外具，低徊龙驭过神州。","翠裀万顷无人捲，弄散珠玑去不收。"]},{"t":"西园梅花","f":"七言绝句","c":["婆律膏融滴蜡开，几多香阵过楼台。","风梅更是相料理，吹到南华枕上来。"]},{"t":"对后园梅花简示诸公","f":"七言绝句","c":["莫讶冷姿浑是雪，若存花态即非梅。","灵根岂受寒拘束，直把阳和竟挽回。"]},{"t":"早梅","f":"七言绝句","c":["一径萦迂入草莱，柴门虽设不曾开。","东风自泄春消息，吹到梅花树下来。"]},{"t":"饮梅花下","f":"七言绝句","c":["除了孤高梅子真，兰生更待与谁亲。","无如清友延清客，有似贤人对圣人。"]},{"t":"梅花引","f":"七言绝句","c":["澹妆素服映冰肌，香袭幽情暗有期。","满地美人心下事，怕拈横玉倚风吹。"]},{"t":"春梅怨笛歌","f":"七言绝句","c":["一声愁笛吟龙起，万点惊香怨雪飞。","珍重冰魂莫回首，酒痕犹满去年衣。"]},{"t":"三月二十二日梦中咏琼花","f":"七言绝句","c":["一树琼花手自栽，栽成盼得到春来。","春来烂漫知多少，羞教群芳不敢开。"]},{"t":"题恋春牡丹","f":"七言绝句","c":["玉籍名延不世香，含情惟务振流芳。","自缘始恋春料理，是索东君力主张。"]},{"t":"牡丹","f":"七言绝句","c":["问谁能养牡丹芽，南枕天津弟一家。","不枉得输青帝力，见闻知是异凡花。"]},{"t":"唐家红紫二色牡丹","f":"七言绝句","c":["谁齐天香凝霞彩，灵根培养列仙家。","汉皇可忍思倾国，鹿走中原是此花。"]},{"t":"题一花二名牡丹","f":"七言绝句","c":["政缘中业擅英声，是索宜专弟一名。","抱一足为天下式，尽消神笔与题评。"]},{"t":"双头牡丹 其一","f":"七言绝句","c":["并倚春风映画堂，相偎应说夜来长。","同枝同叶缘何事，脉脉芳心各自香。"]},{"t":"双头牡丹 其二","f":"七言绝句","c":["玉盘双捧九天香，竞负恩华示宠光。","忆得沈香亭北畔，太真临镜倚新妆。"]},{"t":"带将来","f":"七言绝句","c":["野花新傍玉栏开，长恨何人向此栽。","自是王孙不知道，牡丹根上带将来。"]},{"t":"戏题与牡丹同名芍药","f":"七言绝句","c":["生倚英姿胜玉英，一生香占牡丹名。","县知也是陈惊座，谁许分庭拟抗衡。"]},{"t":"长春芍药同坐客赋","f":"七言绝句","c":["标举孤芳蕴异香，定知经历几炎凉。","自来不受春拘束，显是司花少主张。"]},{"t":"题与牡丹同名芍药","f":"七言绝句","c":["英名窃比儗花王，倾慕花王事业香。","奴隶万花题品处，不应花相敢承当。"]},{"t":"戏题所藏芍药花辞","f":"七言绝句","c":["彫章开发自生春，藻思敷花逐日新。","不独笔端元有舌，为花须可与传神。"]},{"t":"取维扬红玉楼子于层阁芍药种迟而未至","f":"七言绝句","c":["红玉楼当在玉京，千层阁合在层城。","延留应欲腾光价，待合琼花作伴行。"]},{"t":"芍药","f":"七言绝句","c":["杨家一捻红娇润，与醉西施较等差。","倘使红妆无籍在，宝冠须也是閒花。"]},{"t":"墙北桃树","f":"七言绝句","c":["一树缃桃几万枝，馀花落尽未开时。","从今甘比墙南树，长得春风半日迟。"]},{"t":"烧桃树根","f":"七言绝句","c":["碧桃林尽了无痕，溪色无光山色昏。","依旧负薪人不断，采残枝叶更刨根。"]},{"t":"路边桃花","f":"七言绝句","c":["不似刘郎初见时，尘埃憔悴损胭脂。","多情阅尽行人面，醉倚春风果笑谁。"]},{"t":"三月桃花词","f":"七言绝句","c":["春尽山桃花满枝，怨春休道北来迟。","人人正醉春时节，政是江南肠断时。"]},{"t":"日日亭午大风树杪忽见桃花一枝","f":"七言绝句","c":["赢得夭桃衒丽姿，渐教开上最高枝。","司花未必能为地，便是颓风欲起时。"]},{"t":"冬日桃花同诸公赋","f":"七言绝句","c":["碧桃花拥长春洞，秀出元英独自芳。","一点香心瞒客笑，探幽何意与刘郎。"]},{"t":"答王澹游冬日二色桃花诗","f":"七言绝句","c":["冻得梅花开不得，笑他和雪倚阑干。","漫山漫岭知多少，尚对东风怯莫寒。"]},{"t":"落花","f":"七言绝句","c":["瘦绿痴肥怨景浓，一帘红雪压晴空。","惊湍飞去无消息，吹折春心不是风。"]},{"t":"圆福院竹甚茂盛幽都一郡所未有起上人云原有桃树百本余悉去之始植此君因为之赋","f":"七言绝句","c":["忍教仪凤箨龙孙，纵酒刘郎道与存。","应说碧桃花解语，可无桃叶代桃根。"]},{"t":"司春园五月五日梨花是日因事不果 其一","f":"七言绝句","c":["雨迷云梦梦迷春，只自将春认不真。","莫笑独醒人索莫，也须曾是洗妆人。"]},{"t":"司春园五月五日梨花是日因事不果 其二","f":"七言绝句","c":["已是春风酿雪香，月波斜浸玉肌凉。","如何不入荆王梦，却逼何人要洗妆。"]},{"t":"晨诣香山禅寺观两阁前后玉簪","f":"七言绝句","c":["玉簪花映清凉国，露泼冰姿日未升。","只是旧时香世界，水沈香气自薰蒸。"]},{"t":"杨妃菊 其一","f":"七言绝句","c":["追寻秋色到东篱，肠断三郎足别离。","折得一枝香在手，临风何处寄相思。"]},{"t":"杨妃菊 其二","f":"七言绝句","c":["醉浮愁颊半朝红，流恨空遗满六宫。","睡杀海棠春不管，断魂招得嫁春风。"]},{"t":"杨花","f":"七言绝句","c":["游人枉自怨年华，断送春风是此花。","可是东君难管领，一天晴雪过谁家。"]},{"t":"咏苔","f":"七言绝句","c":["露茵叠翠藉閒园，神篆斑斑世未传。","推到东君翻古画，尽输春色买苔钱。"]},{"t":"紫菊","f":"七言绝句","c":["浓改新妆压旧妆，留连春色到秋光。","渊明老后无归客，篱下而今不孙黄。"]},{"t":"乞花","f":"七言绝句","c":["惜花人草乞花诗，欲得花枝慰所思。","计取问花珠玉价，素知都是买花赀。"]},{"t":"戊午冬十一月二十八日过阆州杨氏献小桃十二月二日又献杏花","f":"七言绝句","c":["谁意严凝运化机，小桃生弩绽芳蕤。","东君枉了为春主，开到杏花犹未知。"]},{"t":"惜花御史","f":"七言绝句","c":["春事权舆未渠央，惜花御史似蜂忙。","分明白著千红紫，陪奉宫花为括香。"]},{"t":"锦连钱","f":"七言绝句","c":["锦连钱晕玉连钱，簪袅行吟软玉鞭。","可爱金莲花世界，与人长结画图缘。"]},{"t":"桃花马二首 其一","f":"七言绝句","c":["花满长春洞里开，万枝云锦映楼台。","刘郎不道谁家物，尽与龙媒带取来。"]},{"t":"桃花马二首 其二","f":"七言绝句","c":["散花仙子神如水，閒散瑶花剪霞绮。","春风吹满铁连钱，鞭碎玉鞭鞭不起。"]},{"t":"红叱拨","f":"七言绝句","c":["顾景骄嘶蹑紫烟，绿云随步步金莲。","天然红玉飞香辇，宜载花閒醉玉仙。"]},{"t":"晨鸡","f":"七言绝句","c":["延颈长鸣有所怀，司晨期振宿阴开。","倾心解语扶桑日，直是声声叫出来。"]},{"t":"过琼林园闻莺","f":"七言绝句","c":["神州沈陆宫莺在，不忍频将旧事题。","似与幽人说情绪，尽情啼了又重啼。"]},{"t":"雏莺","f":"七言绝句","c":["一帘疏雨洗清明，啼杀东风陌上莺。","寒勒百花开不得，问他春色与谁争。"]},{"t":"新鹰","f":"七言绝句","c":["逼骆驼山驰快马，近鸳鸯泺案新鹰。","性耽神俊多成癖，非为霜前被冻蝇。"]},{"t":"秋莺","f":"七言绝句","c":["落尽群英一见愁，只因天地雨经秋。","流莺不道春光老，刬地如今调舌柔。"]},{"t":"早春歌","f":"七言绝句","c":["朔风战野地擘裂，震匣瑶琴弦冻折。","春风不意到人间，昨夜柳梢先漏泄。"]},{"t":"白云谣","f":"七言绝句","c":["天花瑞叶将滕六，明与天公示心曲。","一时三表表何事，表曰孤忠三献玉。"]},{"t":"鲋鱼辞","f":"七言绝句","c":["鲋托微波致微意，上自蛟龙至鲟鲤。","今虽得百万江湖，宁比当时斗筲水。"]},{"t":"日将出","f":"七言绝句","c":["阴云夜合乾坤失，万象不能分别得。","苍凉海底浴重光，却与行人指南北。"]},{"t":"五将行","f":"七言绝句","c":["螣蛇游雾相乘势，龙举云兴相借力。","致使云消雾散时，要似枯鱼过江泣。"]},{"t":"秋莲怨","f":"七言绝句","c":["红衣乱委鸳鸯浦，罗袜尘消水仙府。","凝情照景竟无言，应惜芳心为谁苦。"]},{"t":"松声","f":"七言绝句","c":["风低满地蛟龙走，风高万壑龙蛇吼。","苍苍元是岁寒姿，休错思量比蒲柳。"]},{"t":"五禽咏 其一 大麦孰簸箕漏","f":"七言绝句","c":["小麦青青大麦黄，野老啼饥空绕肠。","感大麦孰簸箕漏，惆怅无由除秕糠。"]},{"t":"五禽咏 其二 麦饭孰即快活","f":"七言绝句","c":["长安米贵不易居，粒粒皆比明月珠。","彼麦饭孰即快活，宁知西山有饿夫。"]},{"t":"五禽咏 其三 提葫芦沽美酒","f":"七言绝句","c":["黄垆邈若山与河，人生安乐孰如他。","为提葫芦沽美酒，快唤灵均听浩歌。"]},{"t":"五禽咏 其四 烧香拨火","f":"七言绝句","c":["烧香拨火情发衷，心知有愿天必从。","千声万声祷何事，应祷时和将岁丰。"]},{"t":"五禽咏 其五 不如归去","f":"七言绝句","c":["不如归去不如归，吻裂血啼谁汝知。","便休也把春催去，就去万花深处飞。"]},{"t":"嘲蝶","f":"七言绝句","c":["莫疑庄喜知为蝶，且恐韩凭有化身。","䝼取一生花里活，未宜随定卖花人。"]},{"t":"立秋前一日","f":"七言绝句","c":["大火西流暑气回，青蝇心绪已徘徊。","人言明日新消息，天外秋风刮地来。"]},{"t":"蛙吹","f":"七言绝句","c":["两部难分曲调名，莫疑喧聒是蛙鸣。","谁能碧草清泉上，受用仪同鼓吹声。"]},{"t":"揽镜","f":"七言绝句","c":["月让清光日让圆，翠鸾伏背浸琼筵。","明知富贵自来逼，谁不更教长少年。"]},{"t":"听苗君弹琴","f":"七言绝句","c":["一溪流水漱成冰，六马嘘天四座倾。","未是幽人堪动处，试听徽外两三声。"]},{"t":"听琵琶二首 其一","f":"七言绝句","c":["惊沙槭槭亦纷纷，不觉清霜满鬓根。","寒雁似啼还似说，试临穷发望乌孙。"]},{"t":"听琵琶二首 其二","f":"七言绝句","c":["冷风搜雨雁呼群，点点鸣鸦入暮云。","何事荒寒千万劫，野人甘忍怨昭君。"]},{"t":"渔父叹","f":"七言绝句","c":["直钩钓鳌良可叹，片网图龙真绝痴。","往来江上人无限，鼓掌笑君君不知。"]},{"t":"御床","f":"七言绝句","c":["万国趋观上国光，先皇临御是明堂。","鼎湖龙去无回日，更好教人惜此床。"]},{"t":"大猎诗二首 其一","f":"七言绝句","c":["营表交驰突骑过，射声云布已星罗。","诏官点检貔貅数，奏比年来百万多。"]},{"t":"大猎诗二首 其二","f":"七言绝句","c":["网络周阹万里疆，幅员都是禁围场。","传言羽猎将来到，有诏唯教静虎狼。"]},{"t":"行帐八珍诗四首 其一 醍醐","f":"七言绝句","c":["众珍弹压倒淳熬，甘分教人号老饕。","饕大名非痴醉事，待持杯酒更持螯。"]},{"t":"行帐八珍诗四首 其二 麆沆","f":"七言绝句","c":["玉汁温醇体自然，宛然灵液漱甘泉。","要知天乳流膏露，天也分甘与酒仙。"]},{"t":"行帐八珍诗四首 其三 驼蹄羹","f":"七言绝句","c":["独擅千金济美名，夤缘遗味更腾声。","不应也许教人道，众口难调傅说羹。"]},{"t":"行帐八珍诗四首 其四 驼鹿唇","f":"七言绝句","c":["麟脯谁教冠八珍，不甘腾口说猩唇。","终将此意须通问，曾是调和玉鼎人。"]},{"t":"软玉膏","f":"七言绝句","c":["赤髓薰蒸软玉膏，不消割切与煎熬。","是须更可教人笑，负鼎徘徊困鼓刀。"]},{"t":"行厨","f":"七言绝句","c":["已去取温金鳌酒，还来请煮玉蝉羹。","未妨门外令三老，长是帘前报五更。"]},{"t":"早发清冷泉戏题行厨家僮名三老者","f":"七言绝句","c":["玉液应期养圣胎，万花仙供为人开。","祇从六甲行厨里，径就行窝卒去来。"]},{"t":"茶后偶题","f":"七言绝句","c":["嫩香新汲井华调，簪脚浮花椀面高。","饮罢酒醒江上月，依稀瀛酒一游遨。"]},{"t":"重和惜春诗韵余时经始西园 其一","f":"七言绝句","c":["到底总输开口笑，未妨教效捧心颦。","壶中日月杯中酒，只属莺花旧主人。"]},{"t":"重和惜春诗韵余时经始西园 其二","f":"七言绝句","c":["握月担风留后日，吞花卧酒莫过时。","请君但就溪堂上，更试沈吟味此辞。"]},{"t":"和曹南湖故宫二首 其一","f":"七言绝句","c":["练杀声歌不练兵，霸图应自恃长城。","水流花落将春去，三十六宫空月明。"]},{"t":"和曹南湖故宫二首 其二","f":"七言绝句","c":["香生罗绮纷生光，天上人间白日长。","流水浮云春梦断，夕阳空满旧缭墙。"]},{"t":"和人台城","f":"七言绝句","c":["天下纷纷经几秦，六朝风物问无因。","旧时王谢堂前燕，飞入宫墙不见人。"]},{"t":"和人池亭秋宵思归","f":"七言绝句","c":["风定清烟冷自消，月明秋水浸兰桡。","归心不与游尘息，空混沧波影动摇。"]},{"t":"和德卿秋日海棠","f":"七言绝句","c":["马嵬别后若为容，犹带宫妆醉晕红。","把恨付春春不管，似将馀恨托西风。"]},{"t":"和人茶后有怀友人","f":"七言绝句","c":["玉瓯盈溢仙人掌，云脚浮花雪面堆。","两腋清风归不去，为谁吹上句楼来。"]},{"t":"和光祖","f":"七言绝句","c":["诗篇足继晋名流，几度思君倚寺楼。","十载龙庭归不得，玉泉何日更同游。"]},{"t":"和人韵二首 其一","f":"七言绝句","c":["十分著意送春来，远近人家花尽开。","多谢东君无彼此，笙歌休放紫霞杯。"]},{"t":"和人韵二首 其二","f":"七言绝句","c":["忠臣四海年来少，谗佞满朝日更多。","洒泪问天天不语，不知天意果如何。"]},{"t":"春日席上次高丽国使新安公诗韵二首 其一","f":"七言绝句","c":["绿杨飞尽山城雪，花影满帘春日迟。","事异势殊春是旧，化工著意几曾私。"]},{"t":"春日席上次高丽国使新安公诗韵二首 其二","f":"七言绝句","c":["从来造物閒相弄，自在翻腾梦里身。","人事不知天意思，欲回天地一时春。"]},{"t":"次赵虎岩春思诗韵","f":"七言绝句","c":["惜春弥月醉高楼，不放闲人到上头。","桃李乱随流水去，满城风雨替莺愁。"]},{"t":"次卢希谢冬日桃花诗韵","f":"七言绝句","c":["严风猎猎雪成堆，一夜桃花满院开。","春自不知谁著力，九重天上挽回来。"]},{"t":"次赵虎岩诗韵 其一","f":"七言绝句","c":["读书学剑两无成，牢落无由话此情。","闻道太平公事了，蓬窗閒杀老书生。"]},{"t":"次赵虎岩诗韵 其二","f":"七言绝句","c":["寄语幽都君子儒，年来活计道人居。","而今扰扰封侯辈，大剑长枪不读书。"]},{"t":"次赵虎岩诗韵 其三","f":"七言绝句","c":["玉泉泉下有鱼龙，风起波涛沧海同。","自是鱼龙无意出，月明愁杀钓鱼翁。"]},{"t":"次赵虎岩过玉泉怀古韵 其一","f":"七言绝句","c":["绿回芳草春长在，梦与浮云一段空。","休向玉泉悲故国，咸阳无处问秦宫。"]},{"t":"次赵虎岩过玉泉怀古韵 其二","f":"七言绝句","c":["路僻山荒碧草迷，行人惆怅马频嘶。","当时楼观寻无处，落日疏林鸦乱啼。"]},{"t":"复次过玉泉诗韵四首 其一","f":"七言绝句","c":["玉泉佳景昔人传，近筑幽居碧水前。","他日卜邻无我弃，竹篱茅舍好相连。"]},{"t":"复次过玉泉诗韵四首 其二","f":"七言绝句","c":["玉梅清浅野梅疏，驿路尘空未得书。","独坐穷庐情味恶，漫吟新句寄双鱼。"]},{"t":"复次过玉泉诗韵四首 其三","f":"七言绝句","c":["客梦时时绕玉泉，碧山无数锁苍烟。","君恩未报归难得，且向龙沙待数年。"]},{"t":"复次过玉泉诗韵四首 其四","f":"七言绝句","c":["广文寥落客幽都，我在天涯亦隐居。","料得因循浑忘却，数年不寄一封书。"]},{"t":"拟回文 其一","f":"七言绝句","c":["诗成怨立小桥西，晚日春怀伤鸟啼。","离别书情多寄恨，远山高处暮云低。"]},{"t":"拟回文 其二","f":"七言绝句","c":["楼上独来心上愁，泪垂难道不肠柔。","秋深夜雨风回梦，烛剪空窗暗燄浮。"]},{"t":"即日拟乐天作","f":"七言绝句","c":["从臾新交与旧游，编排酒令与诗筹。","但言误及功名事，便索荒唐改话头。"]},{"t":"答客问","f":"七言绝句","c":["是佛尽居安乐国，无仙不住没愁乡。","听教共献天花供，更管清明分外香。"]},{"t":"继韵为答","f":"七言绝句","c":["日日浮沈卖酒家，不知寒力战风沙。","又谁知道新春色，开到南枝弟几花。"]},{"t":"答李仲玉白发叹","f":"七言绝句","c":["功名江海一浮沤，赚得英雄雪白头。","日月如飞留不住，雁行山色又横秋。"]},{"t":"赠御史","f":"七言绝句","c":["四海嗷嗷属望声，绣衣直指下天庭。","好将罗隐秋虫赋，自此书为座右铭。"]},{"t":"戏赠隐士刘仲明","f":"七言绝句","c":["爱仙无药可登云，爱酒无钱可计春。","只说南山有佳处，如何犹自是闲人。"]},{"t":"秋日行次池上戏赠钓者","f":"七言绝句","c":["垂白穷居野水滨，祇疑秋水是龙津。","神龟己死三千岁，何事持竿不顾人。"]},{"t":"重醉修真宫鍊师","f":"七言绝句","c":["玉检素书鱼附去，锦笺瑶句凤衔来。","桃花流水长春洞，也望群仙许再开。"]},{"t":"读书楼赠道士","f":"七言绝句","c":["道本无名莫强名，在人呈露自然情。","楼头山色门前水，不是天公彩画成。"]},{"t":"为阅俳优诸相赠优歌道士","f":"七言绝句","c":["一曲春风踏踏歌，月光明似镜新磨。","谁游碧落骑鸾凤，记姓蓝人是彩和。"]},{"t":"近体隔句赠人","f":"七言绝句","c":["不知何事伤游子，漫折閒花尽日吟。","转觉忘机是啼鸟，静依芳草说春心。"]},{"t":"戏诸公省集","f":"七言绝句","c":["万事人生前已定，须知祸福不由人。","谁怜四海生灵望，浪著閒钱问鬼神。"]},{"t":"送许大用还浑水","f":"七言绝句","c":["临歧促我送行诗，信笔成诗送子归。","望断碧云天不尽，西风残日雁南飞。"]},{"t":"送刘仲素行","f":"七言绝句","c":["积雪凝云失远岑，西风千里暗惊心。","送君归去寒山外，寂寞归来独怅吟。"]},{"t":"用辅之送晋之诗韵","f":"七言绝句","c":["执手溪边酒一杯，羡君归路过金台。","因风寄语能诗客，囊里新诗早寄来。"]},{"t":"送王彦高","f":"七言绝句","c":["世閒无物可劳神，风外浮云陌上尘。","还笑凤凰城下柳，长条不解挽行人。"]},{"t":"送焦宝国","f":"七言绝句","c":["云压荒凉塞树依，倚楼停酒望君归。","一天风雪晚来定，冻合乾坤鸟不飞。"]},{"t":"送王君璋","f":"七言绝句","c":["半岭斜阳天淡淡，一川衰草角悠悠。","云山望断中州远，衰草斜阳满目愁。"]},{"t":"送侯君美","f":"七言绝句","c":["塞鸿不度暮声哀，况复分襟把一杯。","望断野云人不见，满天风雪下高台。"]},{"t":"送丁仲华","f":"七言绝句","c":["归旆翩翩挽不留，别离诗思为君求。","西风落日重回首，何处青山是宿头。"]},{"t":"送人回游江南","f":"七言绝句","c":["就花便买金钗涧，纵酒休颓玉斗山。","须信人生行乐耳，此行莫问几时还。"]},{"t":"送行人二首 其一","f":"七言绝句","c":["十年鞍马往来程，学剑读书两不成。","故国英雄应笑我，苦吟佳句送人行。"]},{"t":"送行人二首 其二","f":"七言绝句","c":["经过离亭知几度，从前端的一千场。","只疑折尽无情柳，不意东风吹又长。"]},{"t":"送田鍊师行","f":"七言绝句","c":["从侄三山相见稀，又驰云驾几时归。","杨花不领东风管，到处将春自在飞。"]},{"t":"忆李东轩","f":"七言绝句","c":["枚卜云山醉隐居，可能无地置屠苏。","驾飞鸿去翔寥廓，羡杀高人李上都。"]},{"t":"寄李渊","f":"七言绝句","c":["只须剩剪鸳鸯锦，更与重围翡翠楼。","不信西风将白雪，便教吹上远人头。"]},{"t":"寄杨子美","f":"七言绝句","c":["万里关山人去后，一江风雨雁来时。","悠悠自别无消息，漫草新诗寄所思。"]},{"t":"寄国范","f":"七言绝句","c":["旧欢新梦两悠悠，只引相思上驿楼。","尺素不应无寄处，玉滦江抱凤城秋。"]},{"t":"寄李稚川","f":"七言绝句","c":["不堪人坐著风篷，别后俄惊一岁终。","寥落天边倦游客，酒杯何日与君同。"]},{"t":"寄赵虎岩","f":"七言绝句","c":["世态人情但见时，未尝仔细不寻思。","伤心吾道难开口，何处青山约后期。"]},{"t":"睡起有寄","f":"七言绝句","c":["连日轻阴护好花，几场春梦绕天涯。","寻思不记相逢处，又入街西卖酒家。"]},{"t":"贺子所寄","f":"七言绝句","c":["风流玩世酒中仙，独醉仙名盖世传。","诗价一如声价重，且将锦绣裹山川。"]},{"t":"寄家兄","f":"七言绝句","c":["碧云天外寄相思，叠纸封愁鬓欲丝。","一枕晓窗春梦好，东风烂漫小桃枝。"]},{"t":"奉寄郭仲益鍊师","f":"七言绝句","c":["瑶草祇堪尘外种，凤箫当就月中闻。","应怜汉女临溪水，閒洗榴花染白云。"]},{"t":"西斋述事奉寄东都故人","f":"七言绝句","c":["酣觞始得离骚味，恨杀灵均说独醒。","待与解嘲还自笑，默然翻守太元经。"]},{"t":"寄归二首 其一","f":"七言绝句","c":["深掩兰闺定自珍，千金一笑万金身。","笔头无舌倾心事，不著流莺说不真。"]},{"t":"寄归二首 其二","f":"七言绝句","c":["几凭青鸟报芳尘，终是将心寄不真。","一纸短书分付与，蕊珠宫里弄珠人。"]},{"t":"寄人","f":"七言绝句","c":["囊括乾坤计未疏，不知胠箧竟何如。","如何万里惊尘座，未奉平安纸一书。"]},{"t":"春日怀王澹游禧伯","f":"七言绝句","c":["长记寻春信马蹄，画桥流水乱莺啼。","别来往事浑如梦，明月满庭芳草齐。"]},{"t":"怀李舜卿","f":"七言绝句","c":["北来得见鸿音少，南去徒来蝶梦多。","一曲高歌人万里，几回无语上高坡。"]},{"t":"怀曹通甫","f":"七言绝句","c":["流水迢迢芳草匀，相思吟杀倚楼人。","万里关山一壶酒，与谁重醉凤楼春。"]},{"t":"代人作","f":"七言绝句","c":["玉箫抛曲锦停梭，却倚妆楼怨梦多。","心在故园身在客，一声秋雁过滹沱。"]},{"t":"席上和光祖上佥事寿诗韵","f":"七言绝句","c":["素娥檀板象牙床，低按秦筝荐寿觞。","翰林风月三千首，一岁从头上一章。"]},{"t":"为人寿","f":"七言绝句","c":["漫漫寒雪望来迷，喜见孤松渐出堤。","一岁只能生一寸，与君相约碧云齐。"]},{"t":"题寿人八十卷尾","f":"七言绝句","c":["未入非熊惜壮图，却簪黄发掩仙居。","空花不挂真人眼，一任春风撼太虚。"]},{"t":"代书答征西将士抑绝所请","f":"七言绝句","c":["一同游蜀道登天，回首斯须十二年。","老我风神今不似，剑门关内陈场前。"]},{"t":"磨剑行","f":"七言绝句","c":["故国江山梦里行，不期今日果长征。","剑华休遣尘生涩，万事人閒总未平。"]},{"t":"醉去来辞五首 其一","f":"七言绝句","c":["唯有乐天知道者，祇欣欢伯意安哉。","慇勤且莫相回避，著去相将醉去来。"]},{"t":"醉去来辞五首 其二","f":"七言绝句","c":["为慕公和爱啸台，结茅特就北山莱。","须非树挂风瓢处，莫厌歌呼醉去来。"]},{"t":"醉去来辞五首 其三","f":"七言绝句","c":["启事许谁当首肯，谋生休自谩牙欸。","系风捕影非吾事，问柳寻花醉去来。"]},{"t":"醉去来辞五首 其四","f":"七言绝句","c":["日日名花次弟开，看长春色映楼台。","司花可要司春子，准备西园醉去来。"]},{"t":"醉去来辞五首 其五","f":"七言绝句","c":["可爱风流赵素台，与香风引到蓬莱。","诚知宦海风波恶，离了风波醉去来。"]},{"t":"西园仙居亭对雪命酒作白雪嗺 其一","f":"七言绝句","c":["玉花团结就冰桃，玉蕊凝香袭冻醪。","时自唱歌嗺痛饮，踏歌白雪代离骚。"]},{"t":"西园仙居亭对雪命酒作白雪嗺 其二","f":"七言绝句","c":["情知白玉莲花酌，岂抵天然自暖杯。","玉友也须期白雪，缓歌惟命雪儿嗺。"]},{"t":"西园仙居亭对雪命酒作白雪嗺 其三","f":"七言绝句","c":["谁长更得非中圣，自爱惟知是上尊。","只许飞琼歌白雪，缓歌催捲玉昆崙。"]},{"t":"西园仙居亭对雪命酒作白雪嗺 其四","f":"七言绝句","c":["风流天上玉华君，应为花閒种玉人。","延命阳春将白雪，立生春色入壶春。"]},{"t":"西园仙居亭对雪命酒作白雪嗺 其五","f":"七言绝句","c":["浮云盌里酌云液，明月杯中酌月波。","白雪调高谁可和，散花天女与韩娥。"]},{"t":"横笛引 其一","f":"七言绝句","c":["雪梅清瘦怕春知，待结同心与阿谁。","谁许云封将怨笛，引吟龙去陇头吹。"]},{"t":"横笛引 其二","f":"七言绝句","c":["为谁折柳雪长丝，横笛知谁引所思。","春水绿波芳草路，枉教愁杀路傍儿。"]},{"t":"横笛引 其三","f":"七言绝句","c":["落梅流韵游金谷，折柳传情寄玉关。","蕴结长思无计解，只应心曲是连环。"]},{"t":"横笛引 其四","f":"七言绝句","c":["野梅官柳得长生，写出龙吟与凤鸣。","已许云封封怨笛，不教人世有愁声。"]},{"t":"四公子廋辞体四首 其一","f":"七言绝句","c":["细腰宫里芳菲处，唯有金衣公子知。","尝笑何郎暮春怨，绍兰只寄一联诗。"]},{"t":"四公子廋辞体四首 其二","f":"七言绝句","c":["莺穿杨柳金梭织，蝶落宫花玉钱坠。","采花蜂去未回来，一双乳燕梁閒睡。"]},{"t":"四公子廋辞体四首 其三","f":"七言绝句","c":["晓枕啼莺睡起慵，日高墙外趁游蜂。","桃花零落联蝴蝶，燕子来时春意浓。"]},{"t":"四公子廋辞体四首 其四","f":"七言绝句","c":["倚柳穿花自在行，报衙朝夕太劳生。","还家枉结庄周梦，直到西风别玉京。"]},{"t":"少年行","f":"七言绝句","c":["燕燕莺莺满凤城，好花时节更关情。","自从双鲤消池后，惆怅春流越浅清。"]},{"t":"醉吟行","f":"七言绝句","c":["将扶醉玉登华榻，更吐歌珠上绮筵。","两袖春风花下路，得无争指是神仙。"]},{"t":"曲延春","f":"七言绝句","c":["要知今日扶头酒，犹是前时软脚尊。","且恐莺花经冷落，为延风月与温存。"]},{"t":"湿水谣","f":"七言绝句","c":["借问卢沟桥下水，甚时离了湿头山。","自从流入桑乾后，几度穷兵战不还。"]},{"t":"天宝谣","f":"七言绝句","c":["五家队仗丹青里，三辅楼台锦绣中。","不待海棠春睡足，竞随春梦五更风。"]},{"t":"阅史","f":"七言绝句","c":["降得诗魔不抗衡，多情欢伯下愁城。","判花视草风骚将，倚断芸窗阅墨兵。"]},{"t":"读史 其一","f":"七言绝句","c":["琼枝秀出迷春洞，碧月光生媚玉楼。","倾国佳人足倾国，无愁天子得无愁。"]},{"t":"读史 其二","f":"七言绝句","c":["轩辕事业与唐虞，总是规模后世书。","后世玩兵除德让，不知终古更何如。"]},{"t":"乐毅","f":"七言绝句","c":["一举全齐纵二城，风云惨澹五年兵。","奈何不世兴王业，事已垂成閒已行。"]},{"t":"读汲黯传","f":"七言绝句","c":["多欲危言已动心，积薪馀论更骎骎。","足令不得中郎位，枉被人讥泪染襟。"]},{"t":"读王浚传","f":"七言绝句","c":["随波逐浪顺东流，幸得成名下石头。","勾当江南公事了，五湖须更有扁舟。"]},{"t":"读晋书书苍溪石壁","f":"七言绝句","c":["钱神足恶鲁元道，崇让莫推刘子真。","由此尽知当世事，得教怀悯不蒙尘。"]},{"t":"读隋书","f":"七言绝句","c":["二百世犹嫌短促，三千年已是寻常。","神州祇在天西北，天下如何号李唐。"]},{"t":"元夜读唐开元天宝故事","f":"七言绝句","c":["黄阁星繁千炬烛，紫宸花烂百枝灯。","温汤不沃权门火，岂觉渔阳己沸腾。"]},{"t":"月宫游","f":"七言绝句","c":["紫云回曲韵游空，只伴霓裳在月宫。","未到海棠花睡起，岂知愁雨复愁风。"]},{"t":"读裴绿野传","f":"七言绝句","c":["未必求全便自全，事须元自贵天然。","堂堂圣相裴中立，晚节浮沈亦可怜。"]},{"t":"读刘宾客集","f":"七言绝句","c":["仙桃满观红似霞，横得人人处处誇。","前度刘郎应有问，兔葵燕麦又谁家。"]},{"t":"吊王文从之终于泰山","f":"七言绝句","c":["月摇沧海鱼龙泣，风荡荒烟草木号。","自是清名埋不得，巍巍千古泰山高。"]},{"t":"醉读列子","f":"七言绝句","c":["独醉亭中独醉仙，唯知仙道辨逃禅。","等閒嚼蜡横陈际，却味冲虚立命篇。"]},{"t":"观唐太宗像","f":"七言绝句","c":["丹青得许近天真，日表龙姿肖所闻。","功德兼隆古无几，可怜不赎益都君。"]},{"t":"题明皇思曲江图","f":"七言绝句","c":["偃月堂成已祸基，徒令千古罪环儿。","中原战血生荆棘，可惜三郎见事迟。"]},{"t":"题废馆醉仙像","f":"七言绝句","c":["云卧霓裳冷画屏，梦魂应绕旧旗亭。","如今醉著谁家酒，犹自颓然醉不醒。"]},{"t":"题鹤仙梦惊图","f":"七言绝句","c":["梦中了了久忘言，戏写双瞳亦偶然。","万古有形皆幻影，此身初不异丁仙。"]},{"t":"题蓝采和图","f":"七言绝句","c":["终日跹跹舞绿袍，有钱绳串戏儿曹。","争如收脚床头坐，满眼春风醉碧桃。"]},{"t":"题马元章水墨美人图","f":"七言绝句","c":["为嫌脂粉污颜色，故著寻常淡薄衣。","借问赤乌缘底事，惊鱼深入鸟高飞。"]},{"t":"又美人二首 其一","f":"七言绝句","c":["倾危花界总花神，谁计还丹与反真。","难说玉皇惆怅事，分明羞杀月中人。"]},{"t":"又美人二首 其二","f":"七言绝句","c":["衣剪湘云裳剪霞，出门羞落树头花。","东君也雪司花耻，却纵春风乱鬓鸦。"]},{"t":"观画玩蝶美人图","f":"七言绝句","c":["花不知伊蝶不知，粉香旦旦拂花枝。","玉纤不放轻盈去，怕引君王顾盻谁。"]},{"t":"佳人惜梅图","f":"七言绝句","c":["玉骨冰肌瘗雪宫，寿阳残梦捲春空。","不知吹入高楼笛，却挽长条问晓风。"]},{"t":"香迷蛱蝶图","f":"七言绝句","c":["窃处得非韩御史，啖来知是薛瑶英。","只除哲匠生花笔，得把南华梦写成。"]},{"t":"题织成双禽","f":"七言绝句","c":["组工得许近天真，一段幽芳照瑞云。","应是深闺孤恨切，双禽托意学回文。"]},{"t":"太宗马图","f":"七言绝句","c":["大秦热海为封客，大汉炎人乞附庸。","遥想鞭笞天下日，此图应自是云龙。"]},{"t":"题秋江柏石孤舟图","f":"七言绝句","c":["烟涵老柏苍龙瘦，云尽高峰冷翠横。","野渡无人渡秋水，一江秋影浸寒晴。"]},{"t":"跋醉仙图","f":"七言绝句","c":["卧抱春风醉不醒，几时飞得到昆陵。","料来恐泄天机事，也待教人问不应。"]},{"t":"跋彭氏所藏写雁","f":"七言绝句","c":["瘦荻枯荷野水深，画工多意作轻阴。","雪声惊破归飞雁，一片潇湘万里心。"]},{"t":"桃花源上避秦人扇头","f":"七言绝句","c":["碧纱洞里桃花陌，只许刘郎擅好春。","一片兰台风外月，不知元属避秦人。"]},{"t":"题扇头","f":"七言绝句","c":["孤负提携避暑宫，见延明月引清风。","纵然秋风为移夺，终感殊恩在箧中。"]},{"t":"元日上尊大人领省阿钵国夫人寿","f":"七言绝句","c":["莫求天上长生药，己得人閒不老方。","看破古今如一日，年年春色似寻常。"]},{"t":"咏梅谨上尊大人领省","f":"七言绝句","c":["长笑庭花各样妆，竞呈春色占时芳。","孤标冰雪年年伴，只作人閒独自香。"]},{"t":"谨次尊大人领省怀梅溪诗韵","f":"七言绝句","c":["好将元亮林泉兴，澹写王维水墨图。","心远地偏人不到，闭门读尽五车书。"]},{"t":"谨次尊大人领省题灵春园诗韵","f":"七言绝句","c":["万壑云烟增壮观，一壶天地入雄歌。","公侯何物堪人老，自是儿童为揣摩。"]},{"t":"南行寄呈尊大人领省","f":"七言绝句","c":["一梦黄粱不待炊，若为流泪满征衣。","目前西塞身南渡，肠断东风心北飞。"]},{"t":"寄呈 其一","f":"七言绝句","c":["神咏人歌不忍闻，若为天地净妖氛。","重封一纸匡时策，哀乞兰台款奏君。"]},{"t":"寄呈 其二","f":"七言绝句","c":["搔首踌蹰泪满衣，东风浑不管相思。","相思一树梨花发，立到黄昏月上时。"]},{"t":"护先妣国夫人丧南行奉别尊大人领省","f":"七言绝句","c":["泪满云笺未怆神，高楼望不见飞尘。","重重门户无人到，深锁桃花一院春。"]},{"t":"燕城之北垂三十里有瓮山原先妣国夫人坟室在焉予过之哀感不已而贮之诗仍寄呈尊夫大领省以慰其感云 其一","f":"七言绝句","c":["仙佩飘飘驾彩鸾，白云深锁瓮山寒。","自从好梦风吹断，谁念孤儿泪不乾。"]},{"t":"燕城之北垂三十里有瓮山原先妣国夫人坟室在焉予过之哀感不已而贮之诗仍寄呈尊夫大领省以慰其感云 其二","f":"七言绝句","c":["彩鸾飞去几时回，望断青天望不来。","二十二年恩与爱，若为心地不成灰。"]},{"t":"燕城之北垂三十里有瓮山原先妣国夫人坟室在焉予过之哀感不已而贮之诗仍寄呈尊夫大领省以慰其感云 其三","f":"七言绝句","c":["醮台霜冷纸钱灰，醮罢秋风独自回。","满面尘埃人不识，缓驱灰马入城来。"]},{"t":"忆尊大人领省二首 其一","f":"七言绝句","c":["一上居庸万里心，居庸关上望和林。","和林城远望不见，日落云明山水深。"]},{"t":"忆尊大人领省二首 其二","f":"七言绝句","c":["欲回兰棹更夷犹，事出沈思得自求。","霜雁不来书断绝，水寒烟淡倚高楼。"]},{"t":"忆尊大人领省二首 其一","f":"七言绝句","c":["一声长笛野云秋，思上高台最上头。","红叶暮烟人北望，青山落日水东流。"]},{"t":"忆尊大人领省二首 其二","f":"七言绝句","c":["一度思量一度秋，一回伤极一低头。","踌蹰搔首无人会，待下楼来却上楼。"]},{"t":"拜书尊大人领省瓮山原茔域寝园之壁","f":"七言绝句","c":["太平与乱俱无象，先觉分明尽有閒。","閒气欲常游帝所，旱霖终不沃人寰。"]},{"t":"晓闻行宫迁居","f":"七言绝句","c":["曙色将分梦欲残，一天星斗冷阑干。","揽衣推枕出门去，扬子江豪怒晓寒。"]},{"t":"惜别","f":"七言绝句","c":["忆昔相逢各少年，几临风月醉华筵。","悠悠别后空回首，风起杨花雪满天。"]},{"t":"漫兴","f":"七言绝句","c":["谁曾煎得胶黏日，谁解拽将绳系风。","岂道花枝与人面，大都都得几时红。"]},{"t":"信笔","f":"七言绝句","c":["自从得践老成域，曾不更登年少场。","空赋乌栖夜啼曲，可怜谁是贺知章。"]},{"t":"感怀","f":"七言绝句","c":["屈尽人閒薄宦情，千钟从此一毫轻。","人心直要平如水，水面风来更不平。"]},{"t":"所思","f":"七言绝句","c":["望外青山断复连，望中明月缺还圆。","碧云暮合横长笛，目送归鸿不尽天。"]},{"t":"述所思","f":"七言绝句","c":["忍竭声华足笑林，也须当问若为心。","可怜一自施行马，更说重门似海深。"]},{"t":"自笑","f":"七言绝句","c":["独醉仙居独醉亭，只缘耽味洗心经。","可能却使谈天口，唯诵金人背上铭。"]},{"t":"青山","f":"七言绝句","c":["青山不伴青春老，万古千秋色自新。","休去西园桃李醉，晚来风起易愁人。"]},{"t":"无何醉隐","f":"七言绝句","c":["白石先生何日老，青莲居士几时醒。","若须要得留灵景，索与除忧旧福庭。"]},{"t":"对酒吟","f":"七言绝句","c":["莫劳邹律唤春回，雪尽北山空自来。","还笑独醒成底事，壮怀须对酒杯开。"]},{"t":"独自来","f":"七言绝句","c":["日日楼头独自来，别离情事若为裁。","东风倚遍栏干曲，人在天涯回未回。"]},{"t":"春词二首 其一","f":"七言绝句","c":["晚兰香露泣愁红，睡起沈吟绕露丛。","荡子不来花落去，教人怎不怨东风。"]},{"t":"春词二首 其二","f":"七言绝句","c":["空恨勒花春事晚，及开零落却生嫌。","春风若不曾相识，何事频来揭画帘。"]},{"t":"初阅仙音乐","f":"七言绝句","c":["催花白雨衒芳春，香湿霓裳入梦云。","曾是长安年少客，天津桥上月中闻。"]},{"t":"因阅乐戏赠友人","f":"七言绝句","c":["蔷薇露渍霓裳润，桂子风飘月殿香。","犹是蛙鸣耸醉梦，欲教人说是归昌。"]},{"t":"金乐歌","f":"七言绝句","c":["百花气色虽千变，万劫光阴只一般。","金乐既和行乐在，我将天地结心欢。"]},{"t":"明妃二首 其一","f":"七言绝句","c":["汉使却回凭寄语，汉家三十六将军。","劝君莫话封侯事，触拨伤心不愿闻。"]},{"t":"明妃二首 其二","f":"七言绝句","c":["散花天上散花人，谁说香名更未闻。","薄命换移仙寿在，不须青冢有愁云。"]},{"t":"征妇怨","f":"七言绝句","c":["锦织回文织过秋，千丝万缕织成愁。","停梭心口私相问，谁在淩烟阁上头。"]}]};